import { Moon, RefreshCw, Settings, Sun } from 'lucide-react';
import { FullScreenModal } from '../ui/Modal';
import { showToast } from '../ui/Toast';
import { useCampusTheme } from '../../hooks/useCampusTheme';
import { useCampusUpdate } from '../../hooks/useCampusUpdate';
import { channelLabel, sourceKindLabel } from '../../utils/runtimeVersion';

export function AppSettingsScreen({ onClose }: { onClose: () => void }) {
  const { result, busy, hasUpdate, refresh, applyUpdate } = useCampusUpdate();
  const { theme, setTheme } = useCampusTheme();

  const handleUpdate = async () => {
    showToast('正在清理缓存并重新加载界面…', 'info', 2500);
    try {
      await applyUpdate();
    } catch {
      showToast('更新失败，请稍后重试', 'error');
    }
  };

  return (
    <FullScreenModal isOpen={true} onClose={onClose} className="z-20">
      <div className="px-6 py-4 shrink-0 border-b border-border-default/30">
        <h2 className="text-xl font-bold text-text-primary flex items-center gap-2">
          <Settings className="w-6 h-6 text-text-secondary" />
          设置
        </h2>
      </div>
      <div className="flex-1 min-h-0 overflow-y-auto p-5 pb-6 space-y-4 hide-scrollbar">
        <div className="rounded-2xl bg-surface-solid border border-border-default p-4 shadow-sm">
          <div className="font-bold text-text-primary">主题</div>
          <div className="text-[11px] text-text-secondary mt-1">日间与夜间会立刻切换，并记住你的选择</div>
          <div className="grid grid-cols-2 gap-2 mt-3">
            <button
              type="button"
              onClick={() => setTheme('light')}
              className={`flex items-center justify-center gap-1.5 py-2.5 rounded-xl text-xs font-bold border ${
                theme === 'light'
                  ? 'bg-amber-100 text-amber-700 border-amber-200'
                  : 'bg-surface text-text-secondary border-border-default'
              }`}
            >
              <Sun className="w-3.5 h-3.5" />
              日间
            </button>
            <button
              type="button"
              onClick={() => setTheme('dark')}
              className={`flex items-center justify-center gap-1.5 py-2.5 rounded-xl text-xs font-bold border ${
                theme === 'dark'
                  ? 'bg-slate-700 text-white border-slate-500'
                  : 'bg-surface text-text-secondary border-border-default'
              }`}
            >
              <Moon className="w-3.5 h-3.5" />
              夜间
            </button>
          </div>
        </div>
        <div className="rounded-2xl bg-surface-solid border border-border-default p-4 shadow-sm">
          <div className="flex items-start justify-between gap-3">
            <div className="min-w-0">
              <div className="font-bold text-text-primary">更新检测</div>
              <div className="text-[11px] text-text-secondary mt-1 leading-relaxed">
                {result ? `${channelLabel(result.channel)} · ${sourceKindLabel(result.sourceKind)}` : '正在检测…'}
              </div>
              <div className="text-xs text-text-secondary mt-2">
                当前版本 {result?.version || '--'}
                {result?.latest?.version ? ` · 最新 ${result.latest.version}` : ''}
              </div>
              {result?.error && !hasUpdate && (
                <div className="text-[11px] text-rose-400 mt-1">{result.error}</div>
              )}
              {result && !hasUpdate && result.channel === 'release' && (
                <div className="text-[11px] text-emerald-500 mt-1">已是最新版本</div>
              )}
            </div>
            {hasUpdate && (
              <button
                type="button"
                disabled={busy}
                onClick={() => void handleUpdate()}
                className="relative shrink-0 px-3 py-2 rounded-xl bg-rose-500 text-white text-xs font-bold disabled:opacity-60"
              >
                <span className="absolute -top-1 -right-1 w-2.5 h-2.5 rounded-full bg-rose-500 ring-2 ring-white" />
                {busy ? '更新中' : '更新'}
              </button>
            )}
          </div>
          <button
            type="button"
            disabled={busy}
            onClick={() => void refresh().then(() => showToast('已重新检测', 'success', 1500))}
            className="mt-3 flex items-center gap-1.5 text-[11px] font-bold text-text-secondary disabled:opacity-60"
          >
            <RefreshCw className={`w-3.5 h-3.5 ${busy ? 'animate-spin' : ''}`} />
            重新检测
          </button>
        </div>
      </div>
    </FullScreenModal>
  );
}
