import { ChevronDown, Plus } from 'lucide-react';
import { useEffect, useMemo, useState } from 'react';
import { CenterModal } from '../状态栏/src/components/ui/Modal';
import { Gender, TraitOption } from './constants';

interface TraitSelectorProps {
  title: string;
  customLabel: string;
  namePlaceholder: string;
  descriptionPlaceholder: string;
  gender: Gender;
  selectedId: string;
  options: TraitOption[];
  onSelect: (option: TraitOption) => void;
  onCreate: (name: string, description: string) => TraitOption;
}

export function TraitSelector({
  title,
  customLabel,
  namePlaceholder,
  descriptionPlaceholder,
  gender,
  selectedId,
  options,
  onSelect,
  onCreate,
}: TraitSelectorProps) {
  const [expandedId, setExpandedId] = useState<string | null>(selectedId);
  const [creating, setCreating] = useState(false);
  const [customName, setCustomName] = useState('');
  const [customDescription, setCustomDescription] = useState('');
  const canSaveCustom = useMemo(
    () => customName.trim().length > 0 && customDescription.trim().length > 0,
    [customName, customDescription],
  );

  useEffect(() => {
    setExpandedId(selectedId);
  }, [selectedId, gender]);

  const handleSelect = (option: TraitOption) => {
    setExpandedId(option.id);
    onSelect(option);
  };

  const handleSaveCustom = () => {
    if (!canSaveCustom) return;
    const option = onCreate(customName, customDescription);
    handleSelect(option);
    setCustomName('');
    setCustomDescription('');
    setCreating(false);
  };

  return (
    <div className="space-y-2">
      {options.map(option => {
        const selected = selectedId === option.id;
        const expanded = expandedId === option.id;
        return (
          <button
            key={option.id}
            type="button"
            onClick={() => handleSelect(option)}
            className={`w-full text-left rounded-2xl border px-3.5 py-3 transition-all ${
              selected
                ? 'bg-pink-50 border-pink-300 shadow-sm'
                : 'bg-white/70 border-border-default hover:border-pink-200'
            }`}
          >
            <div className="flex items-center justify-between gap-2">
              <div className="flex items-center gap-2 min-w-0">
                <span className={`w-4 h-4 rounded-full border flex items-center justify-center shrink-0 ${selected ? 'border-pink-500 bg-pink-500' : 'border-gray-300 bg-white'}`}>
                  {selected && <span className="w-1.5 h-1.5 rounded-full bg-white" />}
                </span>
                <span className={`text-sm font-bold truncate ${selected ? 'text-pink-700' : 'text-text-primary'}`}>
                  {option.name}
                </span>
                {option.custom && (
                  <span className="text-[10px] font-bold px-1.5 py-0.5 rounded-full bg-rose-100 text-rose-500">自定义</span>
                )}
              </div>
              <ChevronDown className={`w-4 h-4 text-text-secondary transition-transform ${expanded ? 'rotate-180' : ''}`} />
            </div>
            {expanded && option.description && (
              <p className="mt-2 text-xs leading-5 text-text-secondary pl-6">
                {option.description}
              </p>
            )}
          </button>
        );
      })}

      <button
        type="button"
        onClick={() => setCreating(true)}
        className="w-full py-2.5 rounded-2xl border-2 border-dashed border-pink-200 text-pink-500 font-bold text-sm flex items-center justify-center gap-1 bg-pink-50/60 hover:bg-pink-50"
      >
        <Plus className="w-4 h-4" />
        {customLabel}
      </button>

      <CenterModal
        isOpen={creating}
        onClose={() => setCreating(false)}
        className="glass w-[300px] rounded-[20px] border border-white/50 shadow-xl p-4"
      >
        <h3 className="text-base font-bold text-text-primary mb-3">{customLabel}</h3>
        <label className="block mb-3">
          <span className="text-xs font-bold text-text-secondary mb-1.5 block">{title}名称</span>
          <input
            value={customName}
            onChange={e => setCustomName(e.target.value)}
            placeholder={namePlaceholder}
            className="w-full h-10 rounded-xl px-3 bg-white border border-border-default outline-none focus:ring-2 focus:ring-pink-200"
          />
        </label>
        <label className="block mb-4">
          <span className="text-xs font-bold text-text-secondary mb-1.5 block">{title}详情</span>
          <textarea
            value={customDescription}
            onChange={e => setCustomDescription(e.target.value)}
            placeholder={descriptionPlaceholder}
            rows={4}
            className="w-full rounded-xl px-3 py-2 bg-white border border-border-default outline-none focus:ring-2 focus:ring-pink-200 resize-none"
          />
        </label>
        <div className="flex gap-2">
          <button
            type="button"
            onClick={() => setCreating(false)}
            className="flex-1 py-2.5 text-sm font-bold rounded-xl bg-white border border-border-default text-text-secondary"
          >
            取消
          </button>
          <button
            type="button"
            disabled={!canSaveCustom}
            onClick={handleSaveCustom}
            className="flex-1 py-2.5 text-sm font-bold rounded-xl accent-btn disabled:opacity-50"
          >
            保存
          </button>
        </div>
      </CenterModal>
    </div>
  );
}
