export const DEFAULT_RULE_CATEGORIES = [
  '前言',
  '学习纪律',
  '生活纪律',
  '社交礼仪',
  '校园安全',
  '奖惩制度'
] as const;

export type DefaultRuleCategory = typeof DEFAULT_RULE_CATEGORIES[number];

const getCategoryIcon = (category: string) => {
  switch (category) {
    case '前言':
      return BookOpen;
    case '学习纪律':
      return GraduationCap;
    case '生活纪律':
      return Coffee;
    case '社交礼仪':
      return Users;
    case '校园安全':
      return ShieldCheck;
    case '奖惩制度':
      return Scale;
    default:
      return Tag;
  }
};

const getCategoryColor = (category: string) => {
  switch (category) {
    case '前言':
      return {
        bg: 'bg-amber-500/15',
        text: 'text-amber-500',
        border: 'border-amber-400/40',
        badge: 'bg-amber-500/20 text-amber-500',
        gradient: 'from-amber-400 to-orange-400'
      };
    case '学习纪律':
      return {
        bg: 'bg-blue-500/15',
        text: 'text-blue-500',
        border: 'border-blue-400/40',
        badge: 'bg-blue-500/20 text-blue-500',
        gradient: 'from-blue-400 to-indigo-400'
      };
    case '生活纪律':
      return {
        bg: 'bg-emerald-500/15',
        text: 'text-emerald-500',
        border: 'border-emerald-400/40',
        badge: 'bg-emerald-500/20 text-emerald-500',
        gradient: 'from-emerald-400 to-teal-400'
      };
    case '社交礼仪':
      return {
        bg: 'bg-pink-500/15',
        text: 'text-pink-500',
        border: 'border-pink-400/40',
        badge: 'bg-pink-500/20 text-pink-500',
        gradient: 'from-pink-400 to-rose-400'
      };
    case '校园安全':
      return {
        bg: 'bg-rose-500/15',
        text: 'text-rose-500',
        border: 'border-rose-400/40',
        badge: 'bg-rose-500/20 text-rose-500',
        gradient: 'from-rose-500 to-red-500'
      };
    case '奖惩制度':
      return {
        bg: 'bg-purple-500/15',
        text: 'text-purple-400',
        border: 'border-purple-400/40',
        badge: 'bg-purple-500/20 text-purple-400',
        gradient: 'from-purple-400 to-violet-500'
      };
    default:
      return {
        bg: 'bg-sky-500/15',
        text: 'text-sky-400',
        border: 'border-sky-400/40',
        badge: 'bg-sky-500/20 text-sky-400',
        gradient: 'from-sky-400 to-cyan-500'
      };
  }
};

interface RulesScreenProps {
  rules: SchoolRule[];
  buildings: CampusBuilding[];
  onClose: () => void;
  onApplyPending: (rule: SchoolRule) => void;
}

const CategorySelector = ({
  selectedCategory,
  onSelectCategory,
  allCategories,
  onAddNewCategory,
  className
}: {
  selectedCategory: string;
  onSelectCategory: (category: string) => void;
  allCategories: string[];
  onAddNewCategory: (newCat: string) => void;
  className?: string;
}) => {
  const [isOpen, setIsOpen] = useState(false);
  const [tempCategory, setTempCategory] = useState(selectedCategory);
  const [isCreating, setIsCreating] = useState(false);
  const [customInput, setCustomInput] = useState('');
  const dragProps = useDraggableScroll<HTMLDivElement>();

  useEffect(() => {
    if (isOpen) {
      setTempCategory(selectedCategory);
      setIsCreating(false);
      setCustomInput('');
    }
  }, [isOpen, selectedCategory]);

  const handleSave = () => {
    onSelectCategory(tempCategory);
    setIsOpen(false);
  };

  const handleConfirmCreate = () => {
    const trimmed = customInput.trim();
    if (!trimmed) {
      setIsCreating(false);
      return;
    }
    onAddNewCategory(trimmed);
    setTempCategory(trimmed);
    setCustomInput('');
    setIsCreating(false);
    showToast(`已新建分类「${trimmed}」`, 'success');
  };

  const SelectedIcon = getCategoryIcon(selectedCategory);
  const selectedColors = getCategoryColor(selectedCategory);

  return (
    <>
      <button 
        type="button"
        onClick={() => setIsOpen(true)}
        className={className || `w-full h-10 px-3 flex items-center justify-between gap-1.5 rounded-xl transition-all shadow-sm ${selectedColors.bg} ${selectedColors.text} border ${selectedColors.border} hover:opacity-90 cursor-pointer`}
        title="选择校规类型"
      >
        <div className="flex items-center gap-1.5 min-w-0">
          <SelectedIcon className="w-4 h-4 shrink-0" />
          <span className="text-xs font-bold truncate">{selectedCategory}</span>
        </div>
        <ChevronDown className="w-3.5 h-3.5 opacity-50 shrink-0" />
      </button>

      <CenterModal 
        isOpen={isOpen} 
        onClose={() => {
          setIsCreating(false);
          setIsOpen(false);
        }}
        className="glass w-[280px] max-h-[60vh] rounded-[20px] border border-white/50 shadow-xl flex flex-col overflow-hidden"
      >
        {/* Header */}
        <div 
          className="shrink-0 flex items-center justify-between p-4 border-b border-border-default"
          onPointerDown={(e) => e.stopPropagation()}
        >
          <h3 className="text-base font-bold text-text-primary flex items-center gap-2">
            <Tag className="w-4 h-4 text-pink-500" />
            选择校规类型
          </h3>
          <div className="flex items-center gap-1">
            {!isCreating && (
              <button
                type="button"
                onClick={() => setIsCreating(true)}
                className="text-[11px] text-pink-600 hover:text-pink-700 bg-pink-50 hover:bg-pink-100 px-2 py-1 rounded-lg font-bold flex items-center gap-0.5 transition-colors border border-pink-200/60"
              >
                <Plus className="w-3 h-3" />
                新建
              </button>
            )}
            <button 
              onClick={() => {
                setIsCreating(false);
                setIsOpen(false);
              }}
              className="p-1.5 glass rounded-full text-text-secondary hover-fill transition-colors shadow-sm border border-border-default ml-1"
            >
              <X className="w-4 h-4" />
            </button>
          </div>
        </div>

        {/* Inline Create Input when triggered */}
        <AnimatePresence>
          {isCreating && (
            <motion.div 
              initial={{ height: 0, opacity: 0 }}
              animate={{ height: 'auto', opacity: 1 }}
              exit={{ height: 0, opacity: 0 }}
              className="px-3 py-2.5 border-b border-pink-100 bg-pink-50/40 shrink-0"
              onPointerDown={(e) => e.stopPropagation()}
            >
              <div className="flex items-center gap-1.5 w-full">
                <input 
                  type="text"
                  placeholder="新分类名称..."
                  value={customInput}
                  onChange={e => setCustomInput(e.target.value)}
                  onKeyDown={e => {
                    if (e.key === 'Enter') {
                      e.preventDefault();
                      handleConfirmCreate();
                    }
                  }}
                  autoFocus
                  className="flex-1 min-w-0 h-8 glass border border-pink-300 rounded-xl px-2.5 text-xs focus:outline-none focus:ring-2 focus:ring-pink-200 bg-white"
                />
                <button
                  type="button"
                  onClick={handleConfirmCreate}
                  disabled={!customInput.trim()}
                  className="px-2.5 h-8 inline-flex items-center justify-center accent-btn text-xs font-bold rounded-xl transition-colors shrink-0 cursor-pointer whitespace-nowrap disabled:opacity-50"
                >
                  添加
                </button>
                <button
                  type="button"
                  onClick={() => {
                    setIsCreating(false);
                    setCustomInput('');
                  }}
                  className="px-2 h-8 inline-flex items-center justify-center bg-surface hover-fill text-text-secondary text-xs rounded-xl transition-colors shrink-0 cursor-pointer whitespace-nowrap"
                >
                  取消
                </button>
              </div>
            </motion.div>
          )}
        </AnimatePresence>
        
        {/* List content */}
        <div 
          className="flex-1 overflow-y-auto overflow-x-hidden p-3 space-y-2 hide-scrollbar select-none cursor-grab active:cursor-grabbing touch-none"
          {...dragProps} ref={dragProps.ref}
          onPointerDown={(e) => {
            e.stopPropagation();
            if (dragProps.onPointerDown) dragProps.onPointerDown(e);
          }}
        >
          {allCategories.map(cat => {
            const isSelected = tempCategory === cat;
            const Icon = getCategoryIcon(cat);
            const colors = getCategoryColor(cat);
            return (
              <div 
                key={cat} 
                onClick={() => setTempCategory(cat)}
                className={`flex items-center justify-between p-3 rounded-2xl cursor-pointer transition-colors border shadow-sm ${
                  isSelected ? 'bg-pink-500/15 border-pink-400/40' : 'bg-surface-solid border-border-default hover-fill'
                }`}
              >
                <div className="flex items-center gap-3 min-w-0">
                  <div className={`w-4 h-4 rounded-full flex items-center justify-center transition-colors shadow-sm shrink-0 ${
                    isSelected ? 'bg-pink-500 text-white border-pink-500' : 'bg-surface-solid border border-border-default'
                  }`}>
                    {isSelected && <Check className="w-2.5 h-2.5 stroke-[3]" />}
                  </div>
                  <div className={`w-6 h-6 rounded-lg ${colors.bg} ${colors.text} flex items-center justify-center shrink-0 border ${colors.border}`}>
                    <Icon className="w-3.5 h-3.5" />
                  </div>
                  <span className={`text-sm truncate ${isSelected ? 'font-bold text-pink-700' : 'font-medium text-text-primary'}`}>
                    {cat}
                  </span>
                </div>
              </div>
            );
          })}
        </div>

        {/* Footer actions */}
        <div 
          className="shrink-0 p-3 border-t border-border-default flex gap-2"
          onPointerDown={(e) => e.stopPropagation()}
        >
          <button
            onClick={() => {
              setIsCreating(false);
              setIsOpen(false);
            }}
            className="flex-1 py-2.5 text-sm glass text-text-secondary font-bold rounded-xl hover-fill transition-colors shadow-sm border border-border-default"
          >
            取消
          </button>
          <button
            onClick={handleSave}
            className="flex-1 py-2.5 text-sm accent-btn font-bold rounded-xl"
          >
            保存
          </button>
        </div>
      </CenterModal>
    </>
  );
};

function formatLocations(locationNames?: string[]): string {
  if (!locationNames || locationNames.length === 0 || locationNames.includes('全校')) {
    return '全校';
  }
  return locationNames.join('、');
}

function sendRuleCommand(text: string, successMessage: string) {
  if (fillTavernInput(text)) {
    showToast(successMessage, 'success');
    return true;
  }
  showToast('未能写入酒馆输入栏，请手动复制操作文本', 'error');
  return false;
}

export const RulesScreen: React.FC<RulesScreenProps> = ({ rules, buildings, onClose, onApplyPending }) => {
  const [isAddExpanded, setIsAddExpanded] = useState(false);
  const [newTitle, setNewTitle] = useState('');
  const [newContent, setNewContent] = useState('');
  const [newCategory, setNewCategory] = useState<string>('生活纪律');
  const [newLocations, setNewLocations] = useState<string[]>([]);
  const [editingRule, setEditingRule] = useState<SchoolRule | null>(null);
  
  // Custom categories added by user
  const [customCategories, setCustomCategories] = useState<string[]>([]);

  // Calculate all unique categories
  const allCategories = useMemo(() => {
    const defaultList = [...DEFAULT_RULE_CATEGORIES];
    const fromRules = rules.map(r => r.category).filter((c): c is string => Boolean(c));
    const set = new Set([...defaultList, ...customCategories, ...fromRules]);
    return Array.from(set);
  }, [rules, customCategories]);

  // Collapsible category open/close state (collapsed by default)
  const [openCategories, setOpenCategories] = useState<Record<string, boolean>>({});

  const toggleCategoryOpen = (cat: string) => {
    setOpenCategories(prev => ({
      ...prev,
      [cat]: !prev[cat]
    }));
  };

  const isAllExpanded = useMemo(() => {
    return allCategories.length > 0 && allCategories.every(cat => Boolean(openCategories[cat]));
  }, [allCategories, openCategories]);

  const toggleAllCategories = () => {
    const nextState = !isAllExpanded;
    const updated: Record<string, boolean> = {};
    allCategories.forEach(cat => {
      updated[cat] = nextState;
    });
    setOpenCategories(updated);
  };

  const handleAddNewCategory = (newCat: string) => {
    if (!customCategories.includes(newCat) && !DEFAULT_RULE_CATEGORIES.includes(newCat as any)) {
      setCustomCategories(prev => [...prev, newCat]);
    }
    setOpenCategories(prev => ({ ...prev, [newCat]: true }));
  };
  
  const dragProps = useDraggableScroll<HTMLDivElement>();
  const modalDragProps = useDraggableScroll<HTMLDivElement>();

  const checkLocationsExist = (locationNames?: string[]) => {
    if (!locationNames || locationNames.length === 0) return true;
    if (locationNames.includes('全校')) return true;
    return locationNames.every(name => buildings.some(b => b.name === name));
  };

  const handleAddRule = () => {
    if (!newTitle.trim() || !newContent.trim()) return;
    const category = newCategory.trim() || '生活纪律';
    const title = newTitle.trim();
    const content = newContent.trim();
    const locations = formatLocations(newLocations);
    const isNewCategory = !rules.some(rule => rule.category === category);
    const text = isNewCategory
      ? `在校规中新增${category}分类，并于其中新增校规${title}，校规内容为：“${content}”，生效地点为${locations}。`
      : `在校规的${category}分类中新增校规${title}，校规内容为：“${content}”，生效地点为${locations}。`;

    if (!sendRuleCommand(text, '已写入酒馆输入栏，发送后才会更新校规')) {
      return;
    }
    onApplyPending({
      id: `pending-${Date.now()}`,
      title,
      content,
      category,
      locationNames: newLocations.length > 0 ? newLocations : [],
      enabled: true,
      pendingUpdate: true,
      pendingAction: 'add',
    });
    setOpenCategories(prev => ({ ...prev, [category]: true }));
    setNewTitle('');
    setNewContent('');
    setNewLocations([]);
    setIsAddExpanded(false);
  };

  const handleToggle = (rule: SchoolRule) => {
    if (!rule.enabled && rule.locationNames && !checkLocationsExist(rule.locationNames)) {
      showToast('没有对应建筑', 'error');
      return;
    }
    const nextEnabled = !rule.enabled;
    const text = nextEnabled
      ? `将校规「${rule.title}」重新启用，并按原分类「${rule.category || '其他'}」继续生效。`
      : `将校规「${rule.title}」关闭，使其暂时不再生效。`;
    if (!sendRuleCommand(text, nextEnabled ? '已写入启用校规的操作文本' : '已写入关闭校规的操作文本')) {
      return;
    }
    onApplyPending({
      ...rule,
      enabled: nextEnabled,
      pendingUpdate: true,
      pendingAction: 'toggle',
    });
  };

  const handleDelete = (id: string) => {
    const rule = rules.find(item => item.id === id);
    if (!rule) return;
    if (!sendRuleCommand(
      `删除校规「${rule.title}」，该校规原本属于「${rule.category || '其他'}」分类。`,
      '已写入删除校规的操作文本',
    )) {
      return;
    }
    onApplyPending({
      ...rule,
      pendingUpdate: true,
      pendingAction: 'delete',
    });
  };

  const handleEditSave = () => {
    if (!editingRule || !editingRule.title.trim() || !editingRule.content.trim()) return;
    const original = rules.find(item => item.id === editingRule.id);
    const category = editingRule.category?.trim() || '其他';
    const locations = formatLocations(editingRule.locationNames);
    const isNewCategory = !rules.some(rule => rule.category === category && rule.id !== editingRule.id);
    const prefix = isNewCategory ? `在校规中新增${category}分类，并` : '';
    const text = `${prefix}将原校规「${original?.title || editingRule.title}」修改为：标题为「${editingRule.title.trim()}」，分类为「${category}」，校规内容为：“${editingRule.content.trim()}”，生效地点为${locations}。`;
    if (!sendRuleCommand(text, '已写入修改校规的操作文本')) {
      return;
    }
    onApplyPending({
      ...editingRule,
      title: editingRule.title.trim(),
      content: editingRule.content.trim(),
      category,
      locationNames: editingRule.locationNames || [],
      pendingUpdate: true,
      pendingAction: 'edit',
    });
    setOpenCategories(prev => ({ ...prev, [category]: true }));
    setEditingRule(null);
  };

  const handleQuickAddForCategory = (cat: string) => {
    setNewCategory(cat);
    setIsAddExpanded(true);
  };

  // Group rules by category
  const rulesByCategory = useMemo(() => {
    const groups: Record<string, SchoolRule[]> = {};
    allCategories.forEach(cat => {
      groups[cat] = [];
    });
    // Unknown or undefined category group
    const uncategorized: SchoolRule[] = [];

    rules.forEach(rule => {
      const cat = rule.category;
      if (cat && groups[cat]) {
        groups[cat].push(rule);
      } else if (cat) {
        // dynamic category
        if (!groups[cat]) groups[cat] = [];
        groups[cat].push(rule);
      } else {
        uncategorized.push(rule);
      }
    });

    return { groups, uncategorized };
  }, [allCategories, rules]);

  return (
    <FullScreenModal isOpen={true} className="z-20 flex flex-col">
      <style>
        {`
          @keyframes marquee {
            0% { transform: translateX(0); }
            100% { transform: translateX(-50%); }
          }
          .animate-marquee-slow {
            animation: marquee 8s linear infinite;
            display: inline-block;
            white-space: nowrap;
          }
        `}
      </style>
      
      {/* Top Navigation Header */}
      <div className="p-4 sticky top-0 z-10 border-b border-border-default/30">
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-xl font-bold text-text-primary flex items-center gap-2">
              <BookOpen className="w-6 h-6 text-pink-500" />
              校规手册
            </h1>
            <p className="text-[11px] text-text-secondary mt-0.5">
              共 {rules.length} 条校规 · {rules.filter(r => r.enabled).length} 条生效中
            </p>
          </div>
          <div className="flex items-center gap-2">
            <button 
              onClick={toggleAllCategories} 
              className="px-2.5 py-1.5 glass rounded-xl text-xs font-semibold text-text-secondary hover:text-text-primary hover-fill transition-colors shadow-sm flex items-center gap-1 border border-border-default"
              title={isAllExpanded ? "折叠所有分类" : "展开所有分类"}
            >
              <ChevronsUpDown className="w-3.5 h-3.5" />
              <span>{isAllExpanded ? '全部折叠' : '全部展开'}</span>
            </button>
            <button 
              onClick={onClose} 
              className="p-2 glass rounded-full hover-fill transition-colors shadow-sm border border-border-default"
            >
              <ChevronLeft className="w-5 h-5 text-text-primary" />
            </button>
          </div>
        </div>
      </div>
      
      {/* Scrollable Container */}
      <div 
        className="flex-1 min-h-0 overflow-y-auto overflow-x-hidden p-4 space-y-4 pb-6 hide-scrollbar relative select-none cursor-grab active:cursor-grabbing touch-none"
        {...dragProps} ref={dragProps.ref}
      >
        {/* Add New Rule Form */}
        <Card className="flex flex-col overflow-hidden bg-surface p-0 shrink-0 border border-border-default shadow-sm">
          <div 
            onClick={() => setIsAddExpanded(!isAddExpanded)}
            className="p-4 flex items-center justify-between cursor-pointer hover-fill transition-colors"
          >
            <div className="text-sm font-bold text-text-primary flex items-center gap-2">
              <div className="w-7 h-7 rounded-xl accent-btn flex items-center justify-center shadow-xs">
                <Plus className={`w-4 h-4 transition-transform duration-300 ${isAddExpanded ? 'rotate-45' : ''}`} />
              </div>
              <span>添加新校规</span>
            </div>
            <div className="flex items-center gap-1 text-xs text-text-secondary">
              <ChevronDown className={`w-4 h-4 transition-transform duration-300 ${isAddExpanded ? 'rotate-180' : ''}`} />
            </div>
          </div>
          
          <AnimatePresence>
            {isAddExpanded && (
              <motion.div 
                initial={{ height: 0, opacity: 0 }}
                animate={{ height: 'auto', opacity: 1 }}
                exit={{ height: 0, opacity: 0 }}
                className="px-4 pb-4 space-y-3.5 border-t border-pink-50 pt-3"
              >
                {/* Title */}
                <div>
                  <input 
                    type="text" 
                    placeholder="输入校规标题（如：第一条：着装规范）..." 
                    value={newTitle}
                    onChange={e => setNewTitle(e.target.value)}
                    className="w-full h-10 glass border border-border-default rounded-xl px-3 text-sm focus:outline-none focus:ring-2 focus:ring-pink-200 focus:border-pink-300 transition-all shadow-sm bg-white/60 placeholder:text-text-secondary"
                  />
                </div>

                {/* Category & Location */}
                <div className="grid grid-cols-2 gap-2.5">
                  <div>
                    <label className="text-[11px] font-bold text-text-secondary mb-1 flex items-center gap-1">
                      <Tag className="w-3 h-3 text-pink-500" />
                      所属分类
                    </label>
                    <CategorySelector 
                      selectedCategory={newCategory}
                      onSelectCategory={setNewCategory}
                      allCategories={allCategories}
                      onAddNewCategory={handleAddNewCategory}
                    />
                  </div>
                  <div>
                    <label className="text-[11px] font-bold text-text-secondary mb-1 flex items-center gap-1">
                      <MapPin className="w-3 h-3 text-pink-500" />
                      生效地点
                    </label>
                    <LocationSelector 
                      selectedLocations={newLocations}
                      setSelectedLocations={setNewLocations}
                      buildings={buildings}
                    />
                  </div>
                </div>

                {/* Content */}
                <textarea 
                  placeholder="输入校规具体条款内容及违规说明..." 
                  value={newContent}
                  onChange={e => setNewContent(e.target.value)}
                  rows={3}
                  className="w-full glass border border-border-default rounded-xl py-2 px-3 text-sm focus:outline-none focus:ring-2 focus:ring-pink-200 focus:border-pink-300 transition-all shadow-sm bg-white/60 placeholder:text-text-secondary resize-none hide-scrollbar"
                />

                {/* Submit button */}
                <button 
                  onClick={handleAddRule}
                  disabled={!newTitle.trim() || !newContent.trim()}
                  className="w-full py-2.5 accent-btn font-bold rounded-xl transition-all disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-1.5 cursor-pointer"
                >
                  <Check className="w-4 h-4" />
                  <span>写入酒馆输入栏</span>
                </button>
              </motion.div>
            )}
          </AnimatePresence>
        </Card>

        {/* Categorized Collapsible List */}
        <div className="space-y-3.5">
          {allCategories.map(cat => {
            const catRules = rulesByCategory.groups[cat] || [];
            const isOpen = Boolean(openCategories[cat]);
            const Icon = getCategoryIcon(cat);
            const colors = getCategoryColor(cat);
            const enabledCount = catRules.filter(r => r.enabled).length;

            return (
              <div 
                key={cat} 
                className="rounded-2xl border border-border-default bg-surface backdrop-blur-sm overflow-hidden shadow-sm transition-all"
              >
                {/* Collapsible Category Header */}
                <div 
                  onClick={() => toggleCategoryOpen(cat)}
                  className="p-3.5 flex items-center justify-between cursor-pointer hover-fill transition-colors select-none"
                >
                  <div className="flex items-center gap-2.5 min-w-0">
                    <div className={`w-8 h-8 rounded-xl ${colors.bg} ${colors.text} flex items-center justify-center shadow-xs shrink-0 border ${colors.border}`}>
                      <Icon className="w-4 h-4" />
                    </div>
                    <div className="min-w-0">
                      <div className="flex items-center gap-2">
                        <span className="font-bold text-sm text-text-primary truncate">{cat}</span>
                        <span className={`text-[10px] font-bold px-2 py-0.5 rounded-full ${colors.badge}`}>
                          {catRules.length} 条
                        </span>
                      </div>
                    </div>
                  </div>

                  <div className="flex items-center gap-2 shrink-0">
                    {catRules.length > 0 && (
                      <span className="text-[11px] text-text-secondary">
                        {enabledCount > 0 ? `${enabledCount} 条生效` : '已全部关闭'}
                      </span>
                    )}
                    <div className={`w-6 h-6 rounded-full flex items-center justify-center text-text-secondary hover-fill transition-transform duration-300 ${isOpen ? 'rotate-180' : ''}`}>
                      <ChevronDown className="w-4 h-4" />
                    </div>
                  </div>
                </div>

                {/* Collapsible Content */}
                <AnimatePresence initial={false}>
                  {isOpen && (
                    <motion.div
                      initial={{ height: 0, opacity: 0 }}
                      animate={{ height: 'auto', opacity: 1 }}
                      exit={{ height: 0, opacity: 0 }}
                      transition={{ duration: 0.25 }}
                      className="border-t border-border-default/40"
                    >
                      <div className="p-3 space-y-3">
                        {catRules.length > 0 ? (
                          catRules.map(rule => (
                            <RuleCard 
                              key={rule.id} 
                              rule={rule} 
                              buildings={buildings} 
                              onToggle={handleToggle} 
                              onEdit={setEditingRule} 
                              onDelete={handleDelete} 
                            />
                          ))
                        ) : (
                          <div 
                            onClick={() => handleQuickAddForCategory(cat)}
                            className="p-4 rounded-xl border border-dashed border-border-default bg-surface text-center hover-fill transition-colors cursor-pointer group"
                          >
                            <p className="text-xs text-text-secondary font-medium group-hover:text-pink-600 transition-colors">
                              「{cat}」分类下暂无校规
                            </p>
                            <p className="text-[11px] text-pink-500 font-bold mt-1 flex items-center justify-center gap-1">
                              <Plus className="w-3 h-3" />
                              <span>点击在此分类添加新校规</span>
                            </p>
                          </div>
                        )}
                      </div>
                    </motion.div>
                  )}
                </AnimatePresence>
              </div>
            );
          })}

          {/* Uncategorized Rules (if any) */}
          {rulesByCategory.uncategorized.length > 0 && (
            <div className="rounded-2xl border border-border-default bg-surface backdrop-blur-sm overflow-hidden shadow-sm">
              <div 
                onClick={() => toggleCategoryOpen('未分类')}
                className="p-3.5 flex items-center justify-between cursor-pointer hover-fill transition-colors"
              >
                <div className="flex items-center gap-2.5">
                  <div className="w-8 h-8 rounded-xl bg-gray-100 text-gray-600 flex items-center justify-center shadow-xs">
                    <HelpCircle className="w-4 h-4" />
                  </div>
                  <div className="flex items-center gap-2">
                    <span className="font-bold text-sm text-text-primary">未分类校规</span>
                    <span className="text-[10px] font-bold px-2 py-0.5 rounded-full bg-gray-200 text-gray-700">
                      {rulesByCategory.uncategorized.length} 条
                    </span>
                  </div>
                </div>
                <ChevronDown className={`w-4 h-4 text-text-secondary transition-transform duration-300 ${openCategories['未分类'] !== false ? 'rotate-180' : ''}`} />
              </div>

              <AnimatePresence initial={false}>
                {openCategories['未分类'] !== false && (
                  <motion.div
                    initial={{ height: 0, opacity: 0 }}
                    animate={{ height: 'auto', opacity: 1 }}
                    exit={{ height: 0, opacity: 0 }}
                    className="border-t border-border-default/40 p-3 space-y-3"
                  >
                    {rulesByCategory.uncategorized.map(rule => (
                      <RuleCard 
                        key={rule.id} 
                        rule={rule} 
                        buildings={buildings} 
                        onToggle={handleToggle} 
                        onEdit={setEditingRule} 
                        onDelete={handleDelete} 
                      />
                    ))}
                  </motion.div>
                )}
              </AnimatePresence>
            </div>
          )}
        </div>
      </div>

      {/* Edit Modal */}
      <BottomSheetModal 
        isOpen={!!editingRule} 
        onClose={() => setEditingRule(null)}
        className="h-[82%] p-5 bg-white/95 backdrop-blur-xl flex flex-col"
      >
        <div className="flex justify-between items-center mb-3 mt-1 shrink-0">
          <h2 className="text-lg font-bold text-text-primary flex items-center gap-2">
            <BookOpen className="w-5 h-5 text-blue-500" />
            修改校规
          </h2>
          <button 
            onClick={() => setEditingRule(null)}
            className="p-1.5 bg-surface rounded-full text-text-secondary hover-fill transition-colors"
          >
            <X className="w-4 h-4" />
          </button>
        </div>
        
        {editingRule && (
          <div 
            className="flex-1 flex flex-col gap-3.5 overflow-y-auto hide-scrollbar pb-20 relative select-none cursor-grab active:cursor-grabbing touch-none"
            {...modalDragProps} ref={modalDragProps.ref}
          >
            {/* Title */}
            <div>
              <label className="text-xs font-bold text-text-secondary mb-1 block">校规标题</label>
              <input 
                type="text" 
                value={editingRule.title}
                onChange={e => setEditingRule({ ...editingRule, title: e.target.value })}
                className="w-full h-10 glass border border-border-default rounded-xl px-3 text-sm focus:outline-none focus:ring-2 focus:ring-primary/20 focus:border-blue-300 transition-all shadow-sm bg-white/60"
              />
            </div>

            {/* Category & Location */}
            <div className="grid grid-cols-2 gap-2.5">
              <div>
                <label className="text-xs font-bold text-text-secondary mb-1 flex items-center gap-1">
                  <Tag className="w-3.5 h-3.5 text-pink-500" />
                  校规类型
                </label>
                <CategorySelector 
                  selectedCategory={editingRule.category || '生活纪律'}
                  onSelectCategory={cat => setEditingRule({ ...editingRule, category: cat })}
                  allCategories={allCategories}
                  onAddNewCategory={handleAddNewCategory}
                />
              </div>
              <div>
                <label className="text-xs font-bold text-text-secondary mb-1 flex items-center gap-1">
                  <MapPin className="w-3.5 h-3.5 text-pink-500" />
                  生效地点
                </label>
                <LocationSelector 
                  selectedLocations={editingRule.locationNames || []}
                  setSelectedLocations={locs => setEditingRule({ ...editingRule, locationNames: locs.length > 0 ? locs : undefined })}
                  buildings={buildings}
                />
              </div>
            </div>

            {/* Content */}
            <div className="flex-1 flex flex-col z-0">
              <label className="text-xs font-bold text-text-secondary mb-1 block">校规内容</label>
              <textarea 
                value={editingRule.content}
                onChange={e => setEditingRule({ ...editingRule, content: e.target.value })}
                className="flex-1 w-full glass border border-border-default rounded-xl py-2.5 px-3 text-sm focus:outline-none focus:ring-2 focus:ring-primary/20 focus:border-blue-300 transition-all shadow-sm bg-white/60 resize-none hide-scrollbar min-h-[90px]"
              />
            </div>

            {/* Save Button */}
            <button 
              onClick={handleEditSave}
              disabled={!editingRule.title.trim() || !editingRule.content.trim()}
              className="w-full py-3 bg-gradient-to-r from-blue-500 to-indigo-500 hover:from-blue-600 hover:to-indigo-600 text-white font-bold rounded-xl shadow-md transition-colors shrink-0 disabled:opacity-50"
            >
              写入修改到输入栏
            </button>
          </div>
        )}
      </BottomSheetModal>
    </FullScreenModal>
  );
};

