import { Input, Textarea } from '../ui/Input';
import React, { useState, useEffect } from 'react';
import { CampusBuilding, Character, SchoolRule, BuildingEvent, BuildingEventStage } from '../../types';
import { BottomSheetModal } from '../ui/Modal';
import { Map, X, Info, Calendar, Users, BookOpen, Plus, Clock, ChevronDown, ChevronUp, AlertCircle, Edit3, Heart, GraduationCap, User } from 'lucide-react';
import { AnimatePresence, motion } from 'framer-motion';
import { showToast } from '../ui/Toast';
import { useDraggableScroll } from '../../hooks/useDraggableScroll';
import { RuleCard } from '../shared/RuleCard';
import { DateTimePickerModal } from '../shared/DateTimePickerModal';
import { Card } from '../ui/Card';

interface BuildingDetailsModalProps {
  building: CampusBuilding;
  onBuildingsChange: (buildings: CampusBuilding[]) => void;
  characters: Character[];
  rules: SchoolRule[];
  buildings: CampusBuilding[];
  onClose: () => void;
  onCharacterClick: (char: Character) => void;
}

type TabType = 'info' | 'events' | 'characters' | 'rules';

export const BuildingDetailsModal: React.FC<BuildingDetailsModalProps> = ({ building: initialBuilding, onBuildingsChange, characters, buildings, rules, onClose, onCharacterClick }) => {
  // Always derive latest building from `buildings` list
  const building = buildings.find(b => b.id === initialBuilding.id) || initialBuilding;

  // Current time
  const [now, setNow] = useState(Date.now());
  useEffect(() => {
    const timer = setInterval(() => setNow(Date.now()), 10000);
    return () => clearInterval(timer);
  }, []);

  const activeEvents = (building.events || []).filter(e => now >= e.startTime && now <= e.endTime);
  const [activeTab, setActiveTab] = useState<TabType>('info');
  const [expandedEventId, setExpandedEventId] = useState<string | null>(null);
  
  const dragProps = useDraggableScroll<HTMLDivElement>();
  
  // Adding event form state
  const [isAddingEvent, setIsAddingEvent] = useState(false);
  const [newEventName, setNewEventName] = useState('');
  const [newEventDesc, setNewEventDesc] = useState('');
  const [newEventStart, setNewEventStart] = useState('');
  const [newEventEnd, setNewEventEnd] = useState('');
  const [newEventStages, setNewEventStages] = useState<BuildingEventStage[]>([]);
  
  const [newStageName, setNewStageName] = useState('');
  const [newStageDesc, setNewStageDesc] = useState('');
  const [newStageStart, setNewStageStart] = useState('');
  const [newStageEnd, setNewStageEnd] = useState('');
  
  const area = building.width * building.height;
  let sizeLabel = '未知';
  if (area === 1) sizeLabel = '小型';
  else if (area >= 2 && area <= 4) sizeLabel = '中型';
  else if (area >= 5 && area <= 9) sizeLabel = '大型';
  else if (area >= 10 && area <= 16) sizeLabel = '超大型';
  else if (area > 16) sizeLabel = '超大型';

  const activeCharacters = characters.filter(c => c.location === building.name && !c.isHidden);
  
  const buildingRules = rules.filter(r => {
    const isGlobal = !r.locationNames || r.locationNames.length === 0 || r.locationNames.includes('全校');
    if (isGlobal) return false;
    return r.locationNames?.includes(building.name);
  });

  const formatTime = (timestamp: number) => {
    const d = new Date(timestamp);
    return `${d.getMonth()+1}月${d.getDate()}日 ${d.getHours().toString().padStart(2,'0')}:${d.getMinutes().toString().padStart(2,'0')}`;
  };

  const handleAddStage = () => {
    if (!newStageName || !newStageStart || !newStageEnd) {
      showToast('请填写完整环节信息', 'error');
      return;
    }
    const startTs = new Date(newStageStart).getTime();
    const endTs = new Date(newStageEnd).getTime();
    if (startTs >= endTs) {
      showToast('结束时间必须晚于开始时间', 'error');
      return;
    }
    const stage: BuildingEventStage = {
      id: Date.now().toString(),
      name: newStageName,
      description: newStageDesc,
      startTime: startTs,
      endTime: endTs
    };
    setNewEventStages([...newEventStages, stage]);
    setNewStageName('');
    setNewStageDesc('');
    setNewStageStart('');
    setNewStageEnd('');
  };

  const handleAddEvent = () => {
    if (!newEventName || !newEventStart || !newEventEnd) {
      showToast('请填写完整活动信息', 'error');
      return;
    }
    const startTs = new Date(newEventStart).getTime();
    const endTs = new Date(newEventEnd).getTime();
    if (startTs >= endTs) {
      showToast('活动结束时间必须晚于开始时间', 'error');
      return;
    }
    
    const newEvent: BuildingEvent = {
      id: Date.now().toString(),
      name: newEventName,
      description: newEventDesc,
      startTime: startTs,
      endTime: endTs,
      stages: newEventStages
    };
    
    onBuildingsChange(buildings.map(b => {
      if (b.id === building.id) {
        return { ...b, events: [...(b.events || []), newEvent] };
      }
      return b;
    }));
    
    setIsAddingEvent(false);
    setNewEventName('');
    setNewEventDesc('');
    setNewEventStart('');
    setNewEventEnd('');
    setNewEventStages([]);
    showToast('添加活动成功', 'success');
  };

  const toggleExpandEvent = (id: string) => {
    setExpandedEventId(prev => prev === id ? null : id);
  };

  return (
    <BottomSheetModal 
      isOpen={true} 
      onClose={onClose}
      className="p-0 bg-surface-solid rounded-t-3xl shadow-[0_-10px_40px_rgba(0,0,0,0.1)] z-[100] h-[75vh] flex flex-col"
    >
      <style>
        {`
          @keyframes marquee {
            0% { transform: translateX(0); }
            100% { transform: translateX(-50%); }
          }
          .animate-marquee-slow {
            animation: marquee 8s linear infinite;
            display: inline-block;
            white-space: nowrap;
          }
        `}
      </style>
      <div className="p-6 pb-2 shrink-0 border-b border-border-default/30 rounded-t-3xl z-20">
        <div className="flex items-center justify-between">
          <h2 className="text-2xl font-bold text-text-primary flex items-center gap-2">
            <Map className="w-6 h-6 text-pink-500" />
            {building.name}
          </h2>
          <button 
            onClick={onClose}
            className="p-2 bg-surface rounded-full text-text-secondary hover-fill transition-colors"
          >
            <ChevronDown className="w-5 h-5" />
          </button>
        </div>
        
        <div className="flex w-full mt-4 bg-gray-100/80 p-1 rounded-xl">
          {[
            { id: 'info', icon: Info, label: '信息' },
            { id: 'events', icon: Calendar, label: '活动' },
            { id: 'characters', icon: Users, label: '角色' },
            { id: 'rules', icon: BookOpen, label: '规则' }
          ].map(tab => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id as TabType)}
              className={`flex-1 flex items-center justify-center gap-1.5 py-2.5 text-sm font-bold rounded-lg transition-all ${
                activeTab === tab.id 
                  ? 'bg-surface-solid text-pink-600 shadow-sm' 
                  : 'text-text-secondary hover:text-text-primary hover-fill'
              }`}
            >
              <tab.icon className="w-4 h-4" />
              {tab.label}
            </button>
          ))}
        </div>
      </div>
      
      <div 
        className="flex-1 overflow-y-auto overflow-x-hidden p-6 pb-32 space-y-6 hide-scrollbar relative z-10 select-none cursor-grab active:cursor-grabbing touch-none"
        {...dragProps} ref={dragProps.ref}
      >
        <AnimatePresence mode="wait">
          <motion.div
            key={activeTab}
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -10 }}
            transition={{ duration: 0.2 }}
            className="h-full pointer-events-auto"
          >
            {/* ================= INFO TAB ================= */}
            {activeTab === 'info' && (
              <div className="space-y-6">
                <div>
                  <h3 className="text-sm font-bold text-text-secondary mb-2 uppercase tracking-widest">建筑简介</h3>
                  <div className="bg-surface-solid p-4 rounded-2xl shadow-sm border border-border-default text-text-primary leading-relaxed text-sm">
                    {building.description || '暂无详细介绍。'}
                  </div>
                </div>
                
                <div>
                  <div className="flex items-center justify-between bg-surface-solid p-4 rounded-2xl shadow-sm border border-border-default">
                    <span className="text-sm font-bold text-text-secondary">建筑大小</span>
                    <span className="text-sm font-black text-text-primary">{sizeLabel}</span>
                  </div>
                </div>
                
                <div>
                  <h3 className="text-sm font-bold text-text-secondary mb-2 uppercase tracking-widest">当前活动</h3>
                  {activeEvents.length === 0 ? (
                    <div className="bg-white/50 border border-dashed border-border-default p-6 rounded-2xl flex flex-col items-center justify-center gap-2 text-text-secondary">
                      <Calendar className="w-8 h-8 opacity-50" />
                      <span className="text-sm font-bold">此处没有正在进行的活动</span>
                    </div>
                  ) : (
                    <div className="space-y-4">
                      {activeEvents.map(event => {
                        const activeStages = event.stages.filter(s => now >= s.startTime && now <= s.endTime);
                        const isExpanded = expandedEventId === event.id;
                        
                        return (
                          <div key={event.id} className="bg-gradient-to-br from-pink-50/60 to-rose-50/60 border border-pink-200/70 p-4 rounded-2xl shadow-sm relative overflow-hidden">
                            <div className="absolute top-0 left-0 w-1.5 h-full bg-gradient-to-b from-pink-500 to-rose-500"></div>
                            
                            <div 
                              className="flex justify-between items-start cursor-pointer pl-1"
                              onClick={() => toggleExpandEvent(event.id)}
                            >
                              <div className="space-y-1.5 flex-1 pr-2">
                                <h4 className="font-bold text-text-primary text-base flex items-center gap-2">
                                  <span className="relative flex h-2.5 w-2.5 shrink-0">
                                    <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-pink-400 opacity-75"></span>
                                    <span className="relative inline-flex rounded-full h-2.5 w-2.5 bg-pink-500"></span>
                                  </span>
                                  <span>{event.name}</span>
                                </h4>
                                
                                {/* 时间单独成行展示 */}
                                <div className="inline-flex items-center gap-1.5 text-xs text-rose-600 bg-white/80 border border-pink-200/80 px-2.5 py-1 rounded-lg font-medium shadow-xs">
                                  <Clock className="w-3.5 h-3.5 text-pink-500 shrink-0" />
                                  <span>{formatTime(event.startTime)} ~ {formatTime(event.endTime)}</span>
                                </div>

                                {event.description && (
                                  <p className="text-xs text-text-secondary leading-relaxed pt-0.5">{event.description}</p>
                                )}
                              </div>
                              <div className="p-1.5 bg-white/80 rounded-xl text-pink-500 shadow-xs border border-pink-100">
                                {isExpanded ? <ChevronUp className="w-4 h-4" /> : <ChevronDown className="w-4 h-4" />}
                              </div>
                            </div>
                            
                            <AnimatePresence>
                              {isExpanded && (
                                <motion.div 
                                  initial={{ height: 0, opacity: 0 }}
                                  animate={{ height: 'auto', opacity: 1 }}
                                  exit={{ height: 0, opacity: 0 }}
                                  className="overflow-hidden"
                                >
                                  <div className="pt-3 mt-3 border-t border-pink-200/60 space-y-2.5 pl-1">
                                    {event.stages.length === 0 ? (
                                      <div className="text-xs text-text-secondary font-medium">无具体环节信息</div>
                                    ) : (
                                      event.stages.map(stage => {
                                        const isStageActive = now >= stage.startTime && now <= stage.endTime;
                                        return (
                                          <div 
                                            key={stage.id} 
                                            className={`p-3 rounded-xl border ${
                                              isStageActive 
                                                ? 'bg-surface-solid border-pink-300 shadow-sm ring-1 ring-pink-200/50' 
                                                : 'bg-white/70 border-pink-100/70'
                                            } transition-all space-y-1.5`}
                                          >
                                            {/* 环节名称 (第一行) */}
                                            <div className="font-bold text-text-primary text-sm flex items-center gap-1.5">
                                              {isStageActive ? (
                                                <span className="px-1.5 py-0.5 text-[10px] font-bold bg-pink-500 text-white rounded-md shrink-0">进行中</span>
                                              ) : (
                                                <span className="w-1.5 h-1.5 bg-gray-300 rounded-full shrink-0"></span>
                                              )}
                                              <span>{stage.name}</span>
                                            </div>

                                            {/* 环节时间 (第二行) */}
                                            <div className="inline-flex items-center gap-1.5 text-[11px] text-text-secondary bg-pink-50/70 border border-pink-100 px-2 py-0.5 rounded-md font-medium">
                                              <Clock className="w-3 h-3 text-pink-400 shrink-0" />
                                              <span>{formatTime(stage.startTime)} ~ {formatTime(stage.endTime)}</span>
                                            </div>

                                            {/* 环节简介 (第三行) */}
                                            {stage.description && (
                                              <p className="text-xs text-text-secondary leading-relaxed pt-0.5">{stage.description}</p>
                                            )}
                                          </div>
                                        );
                                      })
                                    )}
                                  </div>
                                </motion.div>
                              )}
                            </AnimatePresence>
                          </div>
                        );
                      })}
                    </div>
                  )}
                </div>
              </div>
            )}
            
            {/* ================= EVENTS TAB ================= */}
            {activeTab === 'events' && (
              <div className="space-y-4 pb-12">
                {!isAddingEvent ? (
                  <>
                    <button 
                      onClick={() => setIsAddingEvent(true)}
                      className="w-full py-3 bg-surface-solid border-2 border-dashed border-border-default rounded-2xl text-text-secondary font-bold flex items-center justify-center gap-2 hover:border-pink-300 hover:text-pink-500 transition-colors"
                    >
                      <Plus className="w-5 h-5" /> 添加活动
                    </button>
                    
                    {!(building.events && building.events.length > 0) && (
                      <div className="text-center text-text-secondary text-sm mt-8">暂无建筑活动</div>
                    )}
                    
                    {building.events?.map(event => (
                      <div key={event.id} className="bg-surface-solid rounded-2xl shadow-sm border border-border-default p-4">
                        <div className="flex justify-between items-start">
                          <div className="space-y-1.5 flex-1 pr-2">
                            <h4 className="font-bold text-text-primary text-base">{event.name}</h4>
                            <div className="inline-flex items-center gap-1.5 text-xs text-text-secondary bg-white border border-border-default px-2.5 py-1 rounded-lg font-medium shadow-xs">
                              <Clock className="w-3.5 h-3.5 text-text-secondary shrink-0" />
                              <span>{formatTime(event.startTime)} ~ {formatTime(event.endTime)}</span>
                            </div>
                          </div>
                          <button className="p-2 text-text-secondary hover:text-blue-500 hover:bg-blue-50 rounded-full transition-colors">
                            <Edit3 className="w-4 h-4" />
                          </button>
                        </div>
                        
                        {event.description && (
                          <p className="text-xs text-text-secondary mt-2.5 leading-relaxed">{event.description}</p>
                        )}
                        
                        {event.stages && event.stages.length > 0 && (
                          <div className="mt-4 pt-3 border-t border-border-default space-y-2.5">
                            <div className="text-xs font-bold text-text-secondary uppercase tracking-widest mb-1">活动环节</div>
                            {event.stages.map((stage) => {
                              const isStageActive = now >= stage.startTime && now <= stage.endTime;
                              return (
                                <div key={stage.id} className="p-3 bg-gray-50/80 border border-border-default rounded-xl space-y-1.5">
                                  <div className="font-bold text-text-primary text-sm flex items-center gap-1.5">
                    {isStageActive ? (
                                      <span className="px-1.5 py-0.5 text-[10px] font-bold accent-btn rounded-md shrink-0">进行中</span>
                                    ) : (
                                      <span className="w-1.5 h-1.5 bg-gray-300 rounded-full shrink-0"></span>
                                    )}
                                    <span>{stage.name}</span>
                                  </div>
                                  <div className="inline-flex items-center gap-1.5 text-[11px] text-text-secondary bg-white border border-border-default px-2 py-0.5 rounded-md font-medium">
                                    <Clock className="w-3 h-3 text-text-secondary shrink-0" />
                                    <span>{formatTime(stage.startTime)} ~ {formatTime(stage.endTime)}</span>
                                  </div>
                                  {stage.description && (
                                    <div className="text-xs text-text-secondary leading-relaxed pt-0.5">{stage.description}</div>
                                  )}
                                </div>
                              );
                            })}
                          </div>
                        )}
                      </div>
                    ))}
                  </>
                ) : (
                  <div className="bg-surface-solid rounded-2xl shadow-sm border border-border-default p-5 space-y-4">
                    <div className="flex justify-between items-center mb-2">
                      <h3 className="font-bold text-text-primary">新建活动</h3>
                      <button onClick={() => setIsAddingEvent(false)} className="text-sm font-bold text-text-secondary hover:text-text-secondary">取消</button>
                    </div>
                    
                    <input 
                      type="text" placeholder="活动名称..." 
                      value={newEventName} onChange={e => setNewEventName(e.target.value)}
                      className="w-full bg-gray-50 border border-border-default rounded-xl py-2 px-3 text-sm focus:ring-2 focus:ring-pink-200 focus:outline-none"
                    />
                    <textarea 
                      placeholder="活动简介..." rows={2}
                      value={newEventDesc} onChange={e => setNewEventDesc(e.target.value)}
                      className="w-full bg-gray-50 border border-border-default rounded-xl py-2 px-3 text-sm focus:ring-2 focus:ring-pink-200 focus:outline-none resize-none"
                    />
                    <div className="flex gap-3">
                      <div className="flex-1 w-0">
                        <label className="text-[10px] font-bold text-text-secondary uppercase">开始时间</label>
                        <DateTimePickerModal value={newEventStart} onChange={setNewEventStart} placeholder="选择开始时间" />
                      </div>
                      <div className="flex-1 w-0">
                        <label className="text-[10px] font-bold text-text-secondary uppercase">结束时间</label>
                        <DateTimePickerModal value={newEventEnd} onChange={setNewEventEnd} placeholder="选择结束时间" />
                      </div>
                    </div>
                    
                    <div className="pt-4 border-t border-border-default">
                      <h4 className="text-xs font-bold text-text-secondary uppercase mb-3">添加环节</h4>
                      {newEventStages.map((s, i) => (
                        <div key={i} className="mb-3 p-3 bg-gray-50 rounded-xl text-xs border border-border-default relative">
                          <button onClick={() => setNewEventStages(newEventStages.filter((_, idx) => idx !== i))} className="absolute top-2 right-2 text-rose-500 font-bold">×</button>
                          <div className="font-bold">{s.name}</div>
                          <div className="text-text-secondary scale-90 origin-left">{formatTime(s.startTime)} ~ {formatTime(s.endTime)}</div>
                        </div>
                      ))}
                      
                      <div className="p-3 border border-dashed border-border-default rounded-xl space-y-3">
                        <input type="text" placeholder="环节名称" value={newStageName} onChange={e => setNewStageName(e.target.value)} className="w-full bg-surface-solid border border-border-default rounded-lg py-1.5 px-2 text-xs" />
                        <input type="text" placeholder="环节简介" value={newStageDesc} onChange={e => setNewStageDesc(e.target.value)} className="w-full bg-surface-solid border border-border-default rounded-lg py-1.5 px-2 text-xs" />
                        <div className="flex gap-2">
                          <div className="flex-1 w-0">
                            <DateTimePickerModal value={newStageStart} onChange={setNewStageStart} placeholder="开始时间" className="w-full bg-surface-solid border border-border-default rounded-lg py-1 px-2 text-[10px] text-text-primary focus:ring-2 focus:ring-pink-200" />
                          </div>
                          <div className="flex-1 w-0">
                            <DateTimePickerModal value={newStageEnd} onChange={setNewStageEnd} placeholder="结束时间" className="w-full bg-surface-solid border border-border-default rounded-lg py-1 px-2 text-[10px] text-text-primary focus:ring-2 focus:ring-pink-200" />
                          </div>
                        </div>
                        <button onClick={handleAddStage} className="w-full py-1.5 bg-surface text-text-secondary font-bold text-xs rounded-lg hover-fill">
                          确认添加环节
                        </button>
                      </div>
                    </div>
                    
                    <button onClick={handleAddEvent} className="w-full py-3 mt-4 accent-btn font-bold rounded-xl shadow-sm">
                      保存并添加活动
                    </button>
                  </div>
                )}
              </div>
            )}
            
            {/* ================= CHARACTERS TAB ================= */}
            {activeTab === 'characters' && (
              <div className="space-y-4">
                {activeCharacters.length === 0 ? (
                  <div className="text-center text-text-secondary text-sm mt-8">当前没有角色在这里</div>
                ) : (
                  activeCharacters.map(char => (
                    <Card 
                      key={char.id} 
                      onClick={() => onCharacterClick(char)}
                      className="p-3 flex items-center gap-4 cursor-pointer hover-fill transition-colors relative"
                    >
                      <div className="relative">
                        {char.avatar ? (
                          <img src={char.avatar} className="w-14 h-14 rounded-full object-cover shrink-0 border-2 border-border-default shadow-sm" alt={char.name}/>
                        ) : (
                          <div className="w-14 h-14 rounded-full bg-gradient-to-br from-pink-100 to-rose-100 flex items-center justify-center text-pink-500 font-bold text-lg shrink-0 border-2 border-border-default shadow-sm">
                            {char.name[0]}
                          </div>
                        )}
                      </div>
                      <div className="flex-1 min-w-0 text-left">
                        <div className="flex items-center justify-between mb-1">
                          <span className="font-bold text-text-primary text-base truncate pr-2">{char.name}</span>
                          <div className="flex items-center gap-1 soft-chip px-2 py-0.5 rounded-full">
                            <Heart className="w-3 h-3 fill-current" />
                            <span className="text-xs font-bold">{char.affinity}</span>
                          </div>
                        </div>
                        <div className="text-xs text-text-secondary truncate flex items-center gap-1">
                          <GraduationCap className="w-3.5 h-3.5" />
                          {char.identity || '学生'}
                        </div>
                      </div>
                    </Card>
                  ))
                )}
              </div>
            )}
            
            {/* ================= RULES TAB ================= */}
            {activeTab === 'rules' && (
              <div className="space-y-4 pb-12">
                {buildingRules.length === 0 ? (
                  <div className="text-center text-text-secondary text-sm mt-8">当前建筑没有特殊规则</div>
                ) : (
                  buildingRules.map(rule => (
                    <RuleCard key={rule.id} rule={rule} buildings={buildings} />
                  ))
                )}
              </div>
            )}
          </motion.div>
        </AnimatePresence>
      </div>
    </BottomSheetModal>
  );
};
