import { Trash2 } from 'lucide-react';
import { useMemo, useState } from 'react';
import { ConfirmDialog } from '../状态栏/src/components/ui/ConfirmDialog';
import { CenterModal } from '../状态栏/src/components/ui/Modal';
import { CustomStartForm } from './constants';
import { deleteCustomActivity, loadCustomActivities } from './activities';
import { deleteCustomCampusType, loadCustomCampusTypes } from './campusCatalog';
import { deleteCustomIdentity, loadCustomIdentities } from './identities';
import { formatCampusWorldbook } from './playerArchive';
import { deleteCustomAppearance, deleteCustomPersonality, loadCustomAppearances, loadCustomPersonalities } from './traits';

type PendingDelete = { kind: string; id: string; label: string };

export function ArchiveEditPanel({
  open,
  form,
  onClose,
  onFormChange,
  onCatalogChange,
}: {
  open: boolean;
  form: CustomStartForm;
  onClose: () => void;
  onFormChange: (form: CustomStartForm) => void;
  onCatalogChange: () => void;
}) {
  const [pending, setPending] = useState<PendingDelete | null>(null);
  const [refreshTick, setRefreshTick] = useState(0);
  const campusTypes = useMemo(() => loadCustomCampusTypes(), [open, refreshTick]);
  const looks = useMemo(() => loadCustomAppearances(), [open, refreshTick]);
  const minds = useMemo(() => loadCustomPersonalities(), [open, refreshTick]);
  const identities = useMemo(() => loadCustomIdentities(), [open, refreshTick]);
  const classmates = form.customClassmates || [];
  const activities = useMemo(() => loadCustomActivities(), [open, refreshTick]);

  const groups = [
    { title: '自定义校园类型', items: campusTypes.map(item => ({ kind: 'campus', id: item.id, label: item.name })) },
    { title: '自定义相貌', items: looks.map(item => ({ kind: 'look', id: item.id, label: item.name })) },
    { title: '自定义性格', items: minds.map(item => ({ kind: 'mind', id: item.id, label: item.name })) },
    { title: '自定义身份', items: identities.map(item => ({ kind: 'identity', id: item.id, label: item.name })) },
    { title: '自定义同学', items: classmates.map(item => ({ kind: 'classmate', id: item.name, label: item.name })) },
    { title: '自定义活动', items: activities.map(item => ({ kind: 'activity', id: item.id, label: item.displayName || item.id })) },
  ];
  const empty = groups.every(group => !group.items.length);

  const applyDelete = () => {
    if (!pending) return;
    if (pending.kind === 'campus') {
      deleteCustomCampusType(pending.id);
      if (form.campusType === pending.id) {
        onFormChange({
          ...form,
          campusType: '青春校园',
          campusTrait: '全女',
          campusTraits: ['全女'],
          worldview: formatCampusWorldbook('青春校园', '全女'),
        });
      }
    }
    if (pending.kind === 'look') {
      deleteCustomAppearance(pending.id);
      if (form.appearanceId === pending.id) onFormChange({ ...form, appearanceId: '', appearance: '' });
    }
    if (pending.kind === 'mind') {
      deleteCustomPersonality(pending.id);
      if (form.personalityId === pending.id) onFormChange({ ...form, personalityId: '', personality: '' });
    }
    if (pending.kind === 'identity') {
      deleteCustomIdentity(pending.id);
      if (form.identityId === pending.id) {
        onFormChange({ ...form, identityId: '', identityName: '', identityDescription: '' });
      }
    }
    if (pending.kind === 'classmate') {
      onFormChange({
        ...form,
        customClassmates: classmates.filter(item => item.name !== pending.id),
        selectedClassmateNames: form.selectedClassmateNames.filter(name => name !== pending.id),
      });
    }
    if (pending.kind === 'activity') {
      deleteCustomActivity(pending.id);
      onFormChange({
        ...form,
        selectedActivityNames: (form.selectedActivityNames || []).filter(name => name !== pending.id),
      });
    }
    onCatalogChange();
    setRefreshTick(prev => prev + 1);
    setPending(null);
  };

  return (
    <CenterModal isOpen={open} onClose={onClose} className="w-[calc(100%-2rem)] max-w-[320px] max-h-[80vh] p-0">
      <div className="p-4 border-b border-border-default">
        <h3 className="font-bold text-text-primary">编辑自定义内容</h3>
        <p className="text-[11px] text-text-secondary mt-1">只能删除玩家自己新建的内容，预设项不会出现在这里。</p>
      </div>
      <div className="p-3 space-y-3 overflow-y-auto max-h-[52vh] hide-scrollbar">
        {empty && <p className="text-xs text-text-secondary text-center py-8">还没有可删除的自定义内容</p>}
        {groups.map(group =>
          group.items.length ? (
            <div key={group.title}>
              <p className="text-[11px] font-bold text-text-secondary mb-1.5">{group.title}</p>
              <div className="space-y-1.5">
                {group.items.map(item => (
                  <div key={`${item.kind}-${item.id}`} className="flex items-center gap-2 rounded-xl bg-gray-50 px-2.5 py-2">
                    <span className="flex-1 text-xs font-bold text-text-primary truncate">{item.label}</span>
                    <button type="button" onClick={() => setPending(item)} className="w-8 h-8 rounded-full bg-white text-rose-500 flex items-center justify-center" title="删除">
                      <Trash2 className="w-3.5 h-3.5" />
                    </button>
                  </div>
                ))}
              </div>
            </div>
          ) : null,
        )}
      </div>
      <ConfirmDialog
        open={Boolean(pending)}
        title="确认删除"
        message={pending ? `确定删除「${pending.label}」？此操作不可撤销。` : ''}
        onClose={() => setPending(null)}
        onConfirm={applyDelete}
      />
    </CenterModal>
  );
}
