import React, { useState, useEffect, useRef, UIEvent } from 'react';
import { CenterModal } from '../ui/Modal';
import { Calendar, X } from 'lucide-react';
import { useDraggableScroll } from '../../hooks/useDraggableScroll';

interface DateTimePickerModalProps {
  value: string;
  onChange: (val: string) => void;
  placeholder?: string;
  className?: string;
}

const ScrollColumn = ({ items, value, onChange, label }: { items: string[], value: string, onChange: (v: string) => void, label: string }) => {
  const dragProps = useDraggableScroll<HTMLDivElement>();
  const containerRef = dragProps.ref;
  const isScrolling = useRef(false);
  const scrollTimeout = useRef<NodeJS.Timeout | null>(null);

  // Initialize scroll position when modal opens or value changes externally
  useEffect(() => {
    if (!containerRef.current || isScrolling.current) return;
    const index = items.indexOf(value);
    if (index >= 0) {
      containerRef.current.scrollTop = index * 32;
    }
  }, [value, items]);

  const handleScroll = (e: UIEvent<HTMLDivElement>) => {
    const target = e.target as HTMLDivElement;
    const index = Math.max(0, Math.min(items.length - 1, Math.round(target.scrollTop / 32)));
    
    // Set scrolling flag so we don't trigger the effect above
    isScrolling.current = true;
    if (scrollTimeout.current) clearTimeout(scrollTimeout.current);
    scrollTimeout.current = setTimeout(() => {
      isScrolling.current = false;
    }, 100);

    const newValue = items[index];
    if (newValue !== value) {
      onChange(newValue);
    }
  };

  const handleItemClick = (index: number) => {
    if (containerRef.current) {
      containerRef.current.scrollTo({ top: index * 32, behavior: 'smooth' });
      onChange(items[index]);
    }
  };

  return (
    <div className="flex-1 flex flex-col items-center">
      <span className="text-xs font-bold text-text-secondary mb-2">{label}</span>
      <div className="relative h-40 w-full bg-white/50 rounded-xl border border-border-default overflow-hidden">
        <div className="pointer-events-none absolute top-16 left-0 right-0 h-8 bg-pink-50/50 border-y border-pink-100 z-10"></div>
        <div 
          className="h-full w-full overflow-y-auto overflow-x-hidden hide-scrollbar select-none cursor-grab active:cursor-grabbing touch-none snap-y snap-mandatory relative z-20"
          {...dragProps} 
          ref={containerRef}
          onScroll={handleScroll}
          onPointerDown={(e) => {
            e.stopPropagation();
            if (dragProps.onPointerDown) dragProps.onPointerDown(e);
          }}
        >
          <div className="py-16">
            {items.map((item, idx) => (
              <div 
                key={item}
                onClick={() => handleItemClick(idx)}
                className={`h-8 flex items-center justify-center snap-center cursor-pointer transition-colors ${value === item ? 'text-pink-600 font-bold text-lg' : 'text-text-secondary text-sm hover:text-text-secondary'}`}
              >
                {item}
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
};

export const DateTimePickerModal: React.FC<DateTimePickerModalProps> = ({ value, onChange, placeholder = '选择时间', className }) => {
  const [isOpen, setIsOpen] = useState(false);
  
  const [month, setMonth] = useState('');
  const [day, setDay] = useState('');
  const [hour, setHour] = useState('');
  const [minute, setMinute] = useState('');

  useEffect(() => {
    if (isOpen) {
      const d = value ? new Date(value) : new Date();
      if (isNaN(d.getTime())) return;
      setMonth((d.getMonth() + 1).toString().padStart(2, '0'));
      setDay(d.getDate().toString().padStart(2, '0'));
      setHour(d.getHours().toString().padStart(2, '0'));
      setMinute((Math.floor(d.getMinutes() / 5) * 5).toString().padStart(2, '0')); 
    }
  }, [isOpen, value]);

  const handleSave = () => {
    const year = new Date().getFullYear();
    const formattedMinute = minute.padStart(2, '0');
    const formatted = `${year}-${month}-${day}T${hour}:${formattedMinute}`;
    onChange(formatted);
    setIsOpen(false);
  };

  const months = Array.from({ length: 12 }, (_, i) => (i + 1).toString().padStart(2, '0'));
  const days = Array.from({ length: 31 }, (_, i) => (i + 1).toString().padStart(2, '0'));
  const hours = Array.from({ length: 24 }, (_, i) => i.toString().padStart(2, '0'));
  const minutes = Array.from({ length: 12 }, (_, i) => (i * 5).toString().padStart(2, '0'));

  return (
    <>
      <div 
        onClick={() => setIsOpen(true)}
        className={`flex items-center gap-2 cursor-pointer ${className || 'w-full bg-gray-50 border border-border-default rounded-xl py-2 px-3 text-xs text-text-primary focus:ring-2 focus:ring-pink-200'}`}
      >
        <Calendar className="w-3 h-3 text-text-secondary shrink-0" />
        <span className="truncate flex-1 font-medium">
          {value ? `${month}-${day} ${hour}:${minute.padStart(2, '0')}` : <span className="text-text-secondary">{placeholder}</span>}
        </span>
      </div>

      <CenterModal 
        isOpen={isOpen} 
        onClose={() => setIsOpen(false)}
        className="glass w-[320px] rounded-[24px] border border-white/50 shadow-xl"
      >
        <div 
          className="shrink-0 flex items-center justify-between p-4 border-b border-border-default"
          onPointerDown={(e) => e.stopPropagation()}
        >
          <h3 className="text-base font-bold text-text-primary flex items-center gap-2">
            <Calendar className="w-4 h-4 text-pink-500" />
            选择时间
          </h3>
          <button 
            onClick={() => setIsOpen(false)}
            className="p-1.5 bg-white/50 rounded-full text-text-secondary hover:bg-white/80 transition-colors shadow-sm border border-border-default"
          >
            <X className="w-4 h-4" />
          </button>
        </div>
        
        <div className="p-4 flex gap-2" onPointerDown={(e) => e.stopPropagation()}>
          <ScrollColumn items={months} value={month} onChange={setMonth} label="月" />
          <ScrollColumn items={days} value={day} onChange={setDay} label="日" />
          <ScrollColumn items={hours} value={hour} onChange={setHour} label="时" />
          <ScrollColumn items={minutes} value={minute.padStart(2, '0')} onChange={setMinute} label="分" />
        </div>

        <div 
          className="shrink-0 p-3 border-t border-border-default flex gap-2"
          onPointerDown={(e) => e.stopPropagation()}
        >
          <button
            onClick={() => setIsOpen(false)}
            className="flex-1 py-2.5 text-sm glass text-text-secondary font-bold rounded-xl hover:bg-white/80 transition-colors shadow-sm border border-border-default"
          >
            取消
          </button>
          <button
            onClick={handleSave}
            className="flex-1 py-2.5 text-sm accent-btn font-bold rounded-xl"
          >
            保存
          </button>
        </div>
      </CenterModal>
    </>
  );
};
