export type CampusTheme = 'light' | 'dark';

const STORAGE_KEY = 'campus-app-theme';

function getStorage(): Storage | null {
  try {
    const parent = window.parent && window.parent !== window ? window.parent : window;
    return parent.localStorage;
  } catch {
    try {
      return window.localStorage;
    } catch {
      return null;
    }
  }
}

export function loadCampusTheme(): CampusTheme {
  try {
    const value = getStorage()?.getItem(STORAGE_KEY);
    return value === 'dark' ? 'dark' : 'light';
  } catch {
    return 'light';
  }
}

export function saveCampusTheme(theme: CampusTheme) {
  try {
    getStorage()?.setItem(STORAGE_KEY, theme);
  } catch {
    // ignore
  }
}

export function applyCampusTheme(theme: CampusTheme) {
  const dark = theme === 'dark';
  const toggle = (el: Element | null | undefined) => {
    if (!el) return;
    el.classList.toggle('theme-dark', dark);
  };
  toggle(document.documentElement);
  toggle(document.body);
  try {
    toggle(document.getElementById('root'));
  } catch {
    // ignore
  }
  try {
    document.querySelectorAll('.phone-frame').forEach(toggle);
  } catch {
    // ignore
  }
}

applyCampusTheme(loadCampusTheme());
