import { CenterModal } from './Modal';

export function ConfirmDialog({
  open,
  title,
  message,
  confirmText = '确认删除',
  cancelText = '取消',
  hideCancel = false,
  children,
  onClose,
  onConfirm,
}: {
  open: boolean;
  title: string;
  message: string;
  confirmText?: string;
  cancelText?: string;
  hideCancel?: boolean;
  children?: React.ReactNode;
  onClose: () => void;
  onConfirm: () => void;
}) {
  return (
    <CenterModal isOpen={open} onClose={onClose} className="w-[calc(100%-2rem)] max-w-[280px] p-4">
      <h3 className="text-base font-bold text-text-primary">{title}</h3>
      <p className="text-xs leading-5 text-text-secondary mt-2 whitespace-pre-wrap">{message}</p>
      {children}
      <div className={`flex gap-2 mt-4 ${hideCancel ? '' : ''}`}>
        {!hideCancel && (
          <button type="button" onClick={onClose} className="flex-1 py-2.5 rounded-xl border border-border-default text-sm font-bold text-text-secondary">
            {cancelText}
          </button>
        )}
        <button type="button" onClick={onConfirm} className="flex-1 py-2.5 rounded-xl bg-rose-500 text-white text-sm font-bold">
          {confirmText}
        </button>
      </div>
    </CenterModal>
  );
}
