import { ChevronLeft, ChevronRight, Pencil, Plus, Trash2, X } from 'lucide-react';
import { useEffect, useMemo, useState } from 'react';
import { CenterModal, FullScreenModal } from '../状态栏/src/components/ui/Modal';
import {
  ActivityArchive,
  ActivityClock,
  ActivityForm,
  addCustomActivity,
  buildCalendarCells,
  clampDay,
  clampHour,
  clampMinute,
  clampMonth,
  collectActivityDays,
  createActivitySession,
  daysInMonth,
  emptyActivityForm,
  formatTimeRange,
  loadAllActivities,
  parseActivityArchive,
  parseActivityForm,
  parseTimeRange,
  serializeActivityForm,
  upsertCustomActivity,
  weekdayLabel,
} from './activities';

interface StartTime {
  year: number;
  month: number;
  day: number;
  hour: number;
  minute: number;
}

interface ActivitySelectorProps {
  selectedIds: string[];
  edits: Record<string, string>;
  startTime: StartTime;
  onChange: (payload: { selectedIds: string[]; edits: Record<string, string> }) => void;
  onStartTimeChange: (time: StartTime) => void;
}

const WEEKDAYS = ['一', '二', '三', '四', '五', '六', '日'];

function Field({
  label,
  value,
  onChange,
  placeholder,
  type = 'text',
}: {
  label: string;
  value: string | number;
  onChange: (value: string) => void;
  placeholder?: string;
  type?: string;
}) {
  return (
    <label className="block mb-3 last:mb-0 min-w-0">
      <span className="text-xs font-bold text-text-secondary mb-1.5 block">{label}</span>
      <input
        type={type}
        value={value}
        onChange={event => onChange(event.target.value)}
        placeholder={placeholder}
        className="box-border w-full max-w-full min-w-0 h-10 rounded-xl px-3 bg-white border border-border-default outline-none focus:ring-2 focus:ring-pink-200"
      />
    </label>
  );
}

function TimeRangeFields({
  label,
  value,
  fallbackMonth,
  onChange,
}: {
  label: string;
  value: string;
  fallbackMonth: number;
  onChange: (value: string) => void;
}) {
  const range = parseTimeRange(value, fallbackMonth);
  const setClock = (which: 'start' | 'end', patch: Partial<ActivityClock>) => {
    const nextStart = which === 'start' ? { ...range.start, ...patch } : range.start;
    const nextEnd = which === 'end' ? { ...range.end, ...patch } : range.end;
    onChange(formatTimeRange(nextStart, nextEnd));
  };

  const ClockInputs = ({ clock, which }: { clock: ActivityClock; which: 'start' | 'end' }) => (
    <div className="grid grid-cols-4 gap-1.5">
      {[
        { key: 'month', label: '月', value: clock.month, min: 1, max: 12 },
        { key: 'day', label: '日', value: clock.day, min: 1, max: daysInMonth(2025, clock.month) },
        { key: 'hour', label: '时', value: clock.hour, min: 0, max: 23 },
        { key: 'minute', label: '分', value: clock.minute, min: 0, max: 59 },
      ].map(item => (
        <label key={`${which}-${item.key}`} className="min-w-0">
          <span className="block text-[10px] text-text-secondary mb-1 text-center">{item.label}</span>
          <input
            type="number"
            min={item.min}
            max={item.max}
            value={item.value}
            onChange={event => {
              const raw = Number(event.target.value);
              const nextValue =
                item.key === 'month'
                  ? clampMonth(raw)
                  : item.key === 'day'
                    ? clampDay(2025, clock.month, raw)
                    : item.key === 'hour'
                      ? clampHour(raw)
                      : clampMinute(raw);
              setClock(which, { [item.key]: nextValue } as Partial<ActivityClock>);
            }}
            className="w-full h-9 rounded-xl px-1 text-center bg-white border border-border-default outline-none focus:ring-2 focus:ring-pink-200 text-sm"
          />
        </label>
      ))}
    </div>
  );

  return (
    <div className="mb-3 min-w-0">
      <p className="text-xs font-bold text-text-secondary mb-1.5">{label}</p>
      <p className="text-[10px] text-text-secondary mb-1">开始</p>
      <ClockInputs clock={range.start} which="start" />
      <p className="text-[10px] text-text-secondary mt-2 mb-1">结束</p>
      <ClockInputs clock={range.end} which="end" />
      <p className="mt-2 text-[11px] text-pink-500">{formatTimeRange(range.start, range.end)}</p>
    </div>
  );
}

function ActivityFormFields({ form, onChange }: { form: ActivityForm; onChange: (form: ActivityForm) => void }) {
  const update = <K extends keyof ActivityForm>(key: K, value: ActivityForm[K]) => {
    onChange({ ...form, [key]: value });
  };
  const sessions = form.sessions.length ? form.sessions : [createActivitySession()];
  const range = parseTimeRange(form.time, form.month);

  return (
    <div className="min-w-0 overflow-hidden">
      <Field label="活动名称" value={form.name} onChange={value => update('name', value)} placeholder="如：泳池派对" />
      <Field label="活动地点" value={form.location} onChange={value => update('location', value)} placeholder="如：恒温泳池" />
      <TimeRangeFields
        label="活动时间"
        value={form.time}
        fallbackMonth={form.month}
        onChange={value => {
          const next = parseTimeRange(value, form.month);
          onChange({ ...form, month: next.start.month, time: formatTimeRange(next.start, next.end) });
        }}
      />
      <p className="text-xs font-bold text-text-secondary mb-2">活动环节</p>
      <div className="space-y-3">
        {sessions.map((session, index) => (
          <div key={session.id} className="rounded-xl border border-border-default bg-white p-3 min-w-0">
            <div className="flex items-center gap-2 mb-2">
              <span className="text-[11px] font-bold text-pink-500 shrink-0">环节{index + 1}</span>
              <input
                value={session.title}
                onChange={event => update('sessions', sessions.map(item => (item.id === session.id ? { ...item, title: event.target.value } : item)))}
                placeholder="环节名称"
                className="box-border w-0 min-w-0 flex-1 h-9 rounded-xl px-3 bg-white border border-border-default outline-none focus:ring-2 focus:ring-pink-200"
              />
              {sessions.length > 1 && (
                <button type="button" onClick={() => update('sessions', sessions.filter(item => item.id !== session.id))} className="w-8 h-8 shrink-0 rounded-xl border border-border-default text-text-secondary flex items-center justify-center">
                  <Trash2 className="w-3.5 h-3.5" />
                </button>
              )}
            </div>
            <TimeRangeFields
              label="环节时间"
              value={session.time || form.time}
              fallbackMonth={range.start.month}
              onChange={value => update('sessions', sessions.map(item => (item.id === session.id ? { ...item, time: value } : item)))}
            />
            <label className="block min-w-0">
              <span className="text-xs font-bold text-text-secondary mb-1.5 block">内容</span>
              <textarea value={session.content} onChange={event => update('sessions', sessions.map(item => (item.id === session.id ? { ...item, content: event.target.value } : item)))} rows={5} className="box-border w-full max-w-full min-w-0 rounded-xl px-3 py-2 bg-white border border-border-default outline-none focus:ring-2 focus:ring-pink-200 text-sm leading-6" />
            </label>
          </div>
        ))}
        <button type="button" onClick={() => update('sessions', [...sessions, createActivitySession('', form.time)])} className="w-full py-2 rounded-xl border-2 border-dashed border-pink-200 text-pink-500 text-xs font-bold flex items-center justify-center gap-1 bg-pink-50/60">
          <Plus className="w-3.5 h-3.5" />
          新增环节
        </button>
      </div>
    </div>
  );
}

function pad2(value: number): string {
  return String(value).padStart(2, '0');
}

export function ActivitySelector({ selectedIds, edits, startTime, onChange, onStartTimeChange }: ActivitySelectorProps) {
  const [viewMonth, setViewMonth] = useState(startTime.month);
  const [tick, setTick] = useState(0);
  const [viewing, setViewing] = useState<ActivityArchive | null>(null);
  const [editing, setEditing] = useState(false);
  const [draftForm, setDraftForm] = useState<ActivityForm>(() => emptyActivityForm());
  const [creating, setCreating] = useState(false);
  const [createForm, setCreateForm] = useState<ActivityForm>(() => emptyActivityForm('', startTime.month));

  useEffect(() => {
    setViewMonth(clampMonth(startTime.month));
  }, [startTime.year, startTime.month]);

  const year = startTime.year;
  const currentMonth = clampMonth(startTime.month);
  const currentDay = clampDay(year, currentMonth, startTime.day);
  const cells = useMemo(() => buildCalendarCells(year, viewMonth), [year, viewMonth]);
  const activities = useMemo(
    () =>
      loadAllActivities(year)
        .map(item => parseActivityArchive(item.id, edits[item.id] ?? item.content, item.custom, year))
        .sort((a, b) => a.month - b.month || a.displayName.localeCompare(b.displayName, 'zh-CN')),
    [edits, tick, year],
  );
  const monthActivities = activities.filter(item => {
    const form = parseActivityForm(item.content, item.displayName);
    return item.month === viewMonth || collectActivityDays(form, year, viewMonth).length > 0;
  });
  const markedDays = useMemo(() => {
    const days = new Set<number>();
    for (const item of monthActivities) {
      collectActivityDays(parseActivityForm(item.content, item.displayName), year, viewMonth).forEach(day => days.add(day));
    }
    return days;
  }, [monthActivities, year, viewMonth]);
  const viewingForm = viewing ? parseActivityForm(edits[viewing.id] ?? viewing.content, viewing.displayName) : emptyActivityForm();

  const toggle = (id: string) => {
    onChange({ selectedIds: selectedIds.includes(id) ? selectedIds.filter(item => item !== id) : [...selectedIds, id], edits });
  };

  const shiftMonth = (delta: number) => {
    setViewMonth(prev => {
      const next = prev + delta;
      if (next < 1) return 12;
      if (next > 12) return 1;
      return next;
    });
  };

  const applyStartTime = (patch: Partial<StartTime>) => {
    const next = { ...startTime, ...patch };
    next.month = clampMonth(next.month);
    next.day = clampDay(next.year, next.month, next.day);
    next.hour = Math.min(23, Math.max(0, Math.round(next.hour)));
    next.minute = Math.min(59, Math.max(0, Math.round(next.minute)));
    onStartTimeChange(next);
    if (patch.month != null) setViewMonth(clampMonth(patch.month));
  };

  const openView = (item: ActivityArchive) => {
    setViewing(item);
    setEditing(false);
    setDraftForm(parseActivityForm(edits[item.id] ?? item.content, item.displayName));
  };

  const saveEdit = () => {
    if (!viewing) return;
    const content = serializeActivityForm(draftForm);
    if (viewing.custom) upsertCustomActivity(viewing.id, content);
    onChange({ selectedIds, edits: { ...edits, [viewing.id]: content } });
    setViewing(parseActivityArchive(viewing.id, content, viewing.custom, year));
    setEditing(false);
    setTick(prev => prev + 1);
  };

  const saveCreate = () => {
    if (!createForm.name.trim()) return;
    const created = addCustomActivity(createForm);
    // 新建后不自动勾选，保持与“全部默认不勾选”一致
    onChange({ selectedIds, edits: { ...edits, [created.id]: created.content } });
    setCreating(false);
    setViewMonth(created.month);
    setTick(prev => prev + 1);
  };

  return (
    <div className="space-y-3">
      <div className="rounded-2xl border border-white/80 bg-white/70 px-3 py-2">
        <div className="flex items-center gap-2">
          <p className="min-w-0 flex-1 text-xs font-bold text-pink-600 truncate">
            {year}年{currentMonth}月{currentDay}日 {weekdayLabel(year, currentMonth, currentDay)}
          </p>
          {[
            { key: 'hour', label: '时', value: startTime.hour, min: 0, max: 23 },
            { key: 'minute', label: '分', value: startTime.minute, min: 0, max: 59 },
          ].map(item => (
            <label key={item.key} className="w-14 shrink-0">
              <span className="sr-only">{item.label}</span>
              <input
                type="number"
                min={item.min}
                max={item.max}
                value={item.value}
                onChange={event => applyStartTime({ [item.key]: Number(event.target.value) } as Partial<StartTime>)}
                className="w-full h-8 rounded-lg px-1 text-center bg-white border border-border-default outline-none focus:ring-2 focus:ring-pink-200 text-xs"
              />
            </label>
          ))}
        </div>
      </div>

      <div className="rounded-2xl border border-white/80 bg-white/70 p-3">
        <div className="flex items-center justify-between mb-2">
          <button type="button" onClick={() => shiftMonth(-1)} className="w-8 h-8 rounded-full bg-white border border-border-default flex items-center justify-center">
            <ChevronLeft className="w-4 h-4" />
          </button>
          <p className="text-sm font-bold text-text-primary">{year}年{viewMonth}月</p>
          <button type="button" onClick={() => shiftMonth(1)} className="w-8 h-8 rounded-full bg-white border border-border-default flex items-center justify-center">
            <ChevronRight className="w-4 h-4" />
          </button>
        </div>
        <div className="grid grid-cols-7 gap-1 mb-1">
          {WEEKDAYS.map(label => (
            <div key={label} className="text-center text-[10px] font-bold text-text-secondary py-1">{label}</div>
          ))}
        </div>
        <div className="grid grid-cols-7 gap-1">
          {cells.map((cell, index) => {
            if (!cell.day) return <div key={`empty-${index}`} className="h-9" />;
            const isToday = viewMonth === currentMonth && cell.day === currentDay;
            const hasEvent = markedDays.has(cell.day);
            return (
              <button
                key={cell.day}
                type="button"
                onClick={() => applyStartTime({ month: viewMonth, day: cell.day || 1 })}
                className={`h-9 rounded-xl text-xs font-bold relative ${isToday ? 'accent-btn shadow-sm' : hasEvent ? 'soft-chip' : 'bg-white text-text-primary border border-transparent'}`}
              >
                {cell.day}
                {hasEvent && !isToday && <span className="absolute bottom-1 left-1/2 -translate-x-1/2 w-1 h-1 rounded-full bg-pink-400" />}
              </button>
            );
          })}
        </div>
        <p className="mt-2 text-[11px] text-text-secondary">粉色日期表示当月有活动。点选日期可设为开局当天。</p>
      </div>

      <div className="space-y-2">
        <p className="text-xs font-bold text-text-secondary">{viewMonth}月活动</p>
        {!monthActivities.length && (
          <p className="text-xs text-text-secondary rounded-2xl border border-dashed border-border-default bg-white/60 p-3">这个月还没有预设活动。</p>
        )}
        {monthActivities.map(item => {
          const selected = selectedIds.includes(item.id);
          return (
            <div key={item.id} className={`rounded-2xl border px-3.5 py-3 transition-all ${selected ? 'bg-pink-50 border-pink-300 shadow-sm' : 'bg-white/70 border-border-default'}`}>
              <button type="button" onClick={() => toggle(item.id)} className="w-full text-left">
                <div className="flex items-center justify-between gap-2">
                  <div className="flex items-center gap-2 min-w-0">
                    <span className={`w-4 h-4 rounded-md border flex items-center justify-center shrink-0 ${selected ? 'border-pink-500 bg-pink-500' : 'border-gray-300 bg-white'}`}>
                      {selected && <span className="w-1.5 h-1.5 rounded-sm bg-white" />}
                    </span>
                    <span className={`text-sm font-bold truncate ${selected ? 'text-pink-700' : 'text-text-primary'}`}>{item.displayName}</span>
                    {item.custom && <span className="text-[10px] font-bold px-1.5 py-0.5 rounded-full bg-rose-100 text-rose-500">自定义</span>}
                  </div>
                  <span
                    role="button"
                    tabIndex={0}
                    onClick={event => { event.stopPropagation(); openView(item); }}
                    onKeyDown={event => { if (event.key === 'Enter' || event.key === ' ') { event.preventDefault(); event.stopPropagation(); openView(item); } }}
                    className="shrink-0 text-[11px] font-bold text-pink-500"
                  >
                    编辑
                  </span>
                </div>
                <p className="mt-2 text-xs leading-5 text-text-secondary pl-6">{item.location} · {item.time}</p>
              </button>
            </div>
          );
        })}
      </div>

      <div className="space-y-2">
        <div className="flex items-center justify-between gap-2">
          <p className="text-xs font-bold text-text-secondary">全部活动</p>
          <p className="text-[11px] text-text-secondary shrink-0">
            已选 {selectedIds.length}/{activities.length}
          </p>
        </div>
        {!activities.length && (
          <p className="text-xs text-text-secondary rounded-2xl border border-dashed border-border-default bg-white/60 p-3">
            还没有任何活动。可先新建自定义活动。
          </p>
        )}
        {activities.map(item => {
          const selected = selectedIds.includes(item.id);
          return (
            <div
              key={`all-${item.id}`}
              className={`rounded-2xl border px-3.5 py-3 transition-all ${
                selected ? 'bg-pink-50 border-pink-300 shadow-sm' : 'bg-white/70 border-border-default'
              }`}
            >
              <button type="button" onClick={() => toggle(item.id)} className="w-full text-left">
                <div className="flex items-center justify-between gap-2">
                  <div className="flex items-center gap-2 min-w-0">
                    <span
                      className={`w-4 h-4 rounded-md border flex items-center justify-center shrink-0 ${
                        selected ? 'border-pink-500 bg-pink-500' : 'border-gray-300 bg-white'
                      }`}
                    >
                      {selected && <span className="w-1.5 h-1.5 rounded-sm bg-white" />}
                    </span>
                    <span className={`text-sm font-bold truncate ${selected ? 'text-pink-700' : 'text-text-primary'}`}>
                      {item.displayName}
                    </span>
                    {item.custom && (
                      <span className="text-[10px] font-bold px-1.5 py-0.5 rounded-full bg-rose-100 text-rose-500">
                        自定义
                      </span>
                    )}
                  </div>
                  <span
                    role="button"
                    tabIndex={0}
                    onClick={event => {
                      event.stopPropagation();
                      openView(item);
                    }}
                    onKeyDown={event => {
                      if (event.key === 'Enter' || event.key === ' ') {
                        event.preventDefault();
                        event.stopPropagation();
                        openView(item);
                      }
                    }}
                    className="shrink-0 text-[11px] font-bold text-pink-500"
                  >
                    编辑
                  </span>
                </div>
                <p className="mt-2 text-xs leading-5 text-text-secondary pl-6">
                  {item.month}月 · {item.location} · {item.time}
                </p>
              </button>
            </div>
          );
        })}
      </div>

      <button type="button" onClick={() => { setCreateForm(emptyActivityForm('', viewMonth)); setCreating(true); }} className="w-full py-2.5 rounded-2xl border-2 border-dashed border-pink-200 text-pink-500 font-bold text-sm flex items-center justify-center gap-1 bg-pink-50/60 hover:bg-pink-50">
        <Plus className="w-4 h-4" />
        新建自定义活动
      </button>

      <FullScreenModal isOpen={Boolean(viewing)} className="z-30 pt-12 glass">
        {viewing && (
          <div className="relative flex-1 min-h-0 flex flex-col">
            <div className="px-4 pb-3 flex items-center justify-between">
              <button type="button" onClick={() => setViewing(null)} className="w-9 h-9 rounded-full bg-white/80 border border-border-default flex items-center justify-center text-text-primary" title="返回">
                <ChevronLeft className="w-5 h-5" />
              </button>
              <button type="button" onClick={() => { setDraftForm(viewingForm); setEditing(true); }} className="w-9 h-9 rounded-full bg-white/80 border border-border-default flex items-center justify-center text-pink-500" title="编辑活动">
                <Pencil className="w-4 h-4" />
              </button>
            </div>
            <div className="flex-1 min-h-0 overflow-y-auto px-4 pb-8 hide-scrollbar">
              <div className="rounded-2xl border border-white/80 bg-white/70 p-4 mb-3">
                <p className="text-lg font-bold text-text-primary mb-3">{viewingForm.name || viewing.displayName}</p>
                <p className="text-xs font-bold text-text-secondary mb-1">活动地点</p>
                <p className="text-sm text-text-primary mb-3">{viewingForm.location || '未知地点'}</p>
                <p className="text-xs font-bold text-text-secondary mb-1">活动时间</p>
                <p className="text-sm text-text-primary">{viewingForm.time || '时间未定'}</p>
              </div>
              <p className="text-xs font-bold text-pink-600 mb-2">活动环节</p>
              <div className="space-y-3">
                {viewingForm.sessions.map((session, index) => (
                  <div key={session.id} className="rounded-2xl border border-white/80 bg-white/70 p-4">
                    <p className="text-sm font-bold text-text-primary">环节{index + 1}{session.title ? ` · ${session.title}` : ''}</p>
                    {session.time && <p className="mt-1 text-xs text-text-secondary">时间：{session.time}</p>}
                    <p className="mt-2 text-sm leading-6 text-text-primary whitespace-pre-wrap">{session.content}</p>
                  </div>
                ))}
              </div>
            </div>
          </div>
        )}
      </FullScreenModal>

      <CenterModal isOpen={editing} onClose={() => setEditing(false)} className="glass w-[calc(100%-2rem)] max-w-[300px] min-w-0 h-[80vh] max-h-[80vh] rounded-[20px] border border-white/50 shadow-xl p-0 box-border">
        <div className="min-h-0 flex-1 overflow-y-auto overflow-x-hidden p-4 hide-scrollbar overscroll-contain touch-pan-y">
          <div className="flex items-center justify-between mb-3">
            <h3 className="text-base font-bold text-text-primary">编辑活动</h3>
            <button type="button" onClick={() => setEditing(false)} className="w-8 h-8 rounded-full bg-white border border-border-default flex items-center justify-center">
              <X className="w-4 h-4 text-text-secondary" />
            </button>
          </div>
          <ActivityFormFields form={draftForm} onChange={setDraftForm} />
          <div className="flex gap-2 mt-4">
            <button type="button" onClick={() => setEditing(false)} className="flex-1 py-2.5 text-sm font-bold rounded-xl bg-white border border-border-default text-text-secondary">取消</button>
            <button type="button" onClick={saveEdit} className="flex-1 py-2.5 text-sm font-bold rounded-xl accent-btn">保存</button>
          </div>
        </div>
      </CenterModal>

      <CenterModal isOpen={creating} onClose={() => setCreating(false)} className="glass w-[calc(100%-2rem)] max-w-[300px] min-w-0 h-[80vh] max-h-[80vh] rounded-[20px] border border-white/50 shadow-xl p-0 box-border">
        <div className="min-h-0 flex-1 overflow-y-auto overflow-x-hidden p-4 hide-scrollbar overscroll-contain touch-pan-y">
          <h3 className="text-base font-bold text-text-primary mb-3">新建自定义活动</h3>
          <ActivityFormFields form={createForm} onChange={setCreateForm} />
          <div className="flex gap-2 mt-4">
            <button type="button" onClick={() => setCreating(false)} className="flex-1 py-2.5 text-sm font-bold rounded-xl bg-white border border-border-default text-text-secondary">取消</button>
            <button type="button" disabled={!createForm.name.trim()} onClick={saveCreate} className="flex-1 py-2.5 text-sm font-bold rounded-xl accent-btn disabled:opacity-50">保存</button>
          </div>
        </div>
      </CenterModal>
    </div>
  );
}
