import React, { useState, useMemo } from 'react';
import { Character, ChatGroup, Player } from '../../types';
import { motion, Reorder, useDragControls } from 'framer-motion';
import { BookUser, Heart, Search, ChevronLeft, Pin, Trash2, Users } from 'lucide-react';
import { useDraggableScroll } from '../../hooks/useDraggableScroll';
import { SwipeableItem } from '../shared/SwipeableItem';
import { FullScreenModal, BottomSheetModal } from '../ui/Modal';
import { Card } from '../ui/Card';
import { ChatScreen } from './ChatScreen';
import { useChatThreads } from '../../hooks/useChatThreads';
import { useMvuSnapshot } from '../../hooks/useMvuData';
import { mvuTimeToTimestamp } from '../../utils/forumParser';
import { getCharacterChatAliases, getChatDisplayName, getLatestPreview, getThreadMessages } from '../../utils/chatParser';

const LongPressReorderItem: React.FC<{ char: Character, disabled: boolean, children: React.ReactNode }> = ({ char, disabled, children }) => {
  const controls = useDragControls();
  const [isDragging, setIsDragging] = useState(false);
  const [isReady, setIsReady] = useState(false);

  const handlePointerDown = (e: React.PointerEvent) => {
    if (disabled) return;
    const startX = e.clientX;
    const startY = e.clientY;

    const timeout = setTimeout(() => {
       setIsReady(true);
       setTimeout(() => setIsReady(false), 500);
       controls.start(e);
       cleanup();
    }, 400); // 400ms for long press

    const cleanup = () => {
       clearTimeout(timeout);
       window.removeEventListener('pointerup', cleanup);
       window.removeEventListener('pointercancel', cleanup);
       window.removeEventListener('pointermove', onMove);
    };

    const onMove = (moveEvent: PointerEvent) => {
       const dx = moveEvent.clientX - startX;
       const dy = moveEvent.clientY - startY;
       // If moved more than 10px, cancel long press
       if (Math.abs(dx) > 10 || Math.abs(dy) > 10) {
           cleanup();
       }
    };

    window.addEventListener('pointerup', cleanup, { once: true });
    window.addEventListener('pointercancel', cleanup, { once: true });
    window.addEventListener('pointermove', onMove);
  };

  return (
    <Reorder.Item 
      value={char} 
      dragListener={false} 
      dragControls={controls}
      onDragStart={() => setIsDragging(true)}
      onDragEnd={() => setTimeout(() => setIsDragging(false), 200)}
      onPointerDown={handlePointerDown}
      onClickCapture={(e) => {
        if (isDragging) {
          e.stopPropagation();
          e.preventDefault();
        }
      }}
    >
      <motion.div
        animate={isReady ? {
          scale: [1, 1.05, 0.95, 1.02, 1],
          y: [0, -5, 0, -2, 0],
        } : {}}
        transition={isReady ? { duration: 0.4 } : {}}
      >
        {children}
      </motion.div>
    </Reorder.Item>
  );
}

interface ContactsScreenProps {
  characters: Character[];
  setCharacters: React.Dispatch<React.SetStateAction<Character[]>>;
  groups: ChatGroup[];
  player: Player;
  onCharacterClick: (char: Character) => void;
  onClose: () => void;
}

 /**
 * 同学录模块 (ContactsScreen)
 * 展示所有可互动的角色列表，支持搜索、置顶、隐藏、排序功能
 * @param characters - 角色列表数据
 * @param setCharacters - 更新角色列表数据的状态函数
 * @param onCharacterClick - 点击角色触发的回调，用于查看角色详情
 * @param onClose - 关闭同学录界面的回调
 */
export const ContactsScreen: React.FC<ContactsScreenProps> = ({ characters, setCharacters, groups, player, onCharacterClick, onClose }) => {
  const dragProps = useDraggableScroll<HTMLDivElement>();
  const hiddenDragProps = useDraggableScroll<HTMLDivElement>();
  const [searchTerm, setSearchTerm] = useState('');
  const [showHiddenModal, setShowHiddenModal] = useState(false);
  const [tab, setTab] = useState<'mates' | 'groups'>('mates');
  const [activeChat, setActiveChat] = useState<{ type: 'dm' | 'group'; target: string; characterId?: string } | null>(null);
  const threads = useChatThreads();
  const mvuData = useMvuSnapshot();
  const nowTs = mvuTimeToTimestamp(mvuData.时间);

  /**
   * 处理角色的置顶/取消置顶操作
   * @param id - 被操作角色的唯一 ID
   * @param currentPin - 当前该角色的置顶状态 (true 为已置顶，false 为未置顶)
   */
  const handlePin = (id: string, currentPin: boolean) => {
    setCharacters(prev => {
      const char = prev.find(c => c.id === id);
      if (!char) return prev;
      const updated = { ...char, isPinned: !currentPin, pinnedAt: !currentPin ? Date.now() : undefined };
      const others = prev.filter(c => c.id !== id);
      if (!currentPin) {
        // Pinning: add to top of pinned
        const pinned = others.filter(c => c.isPinned);
        const unpinned = others.filter(c => !c.isPinned);
        return [...pinned, updated, ...unpinned];
      } else {
        // Unpinning: add to top of unpinned
        const pinned = others.filter(c => c.isPinned);
        const unpinned = others.filter(c => !c.isPinned);
        return [...pinned, updated, ...unpinned];
      }
    });
  };

  /**
   * 处理角色的隐藏操作
   * @param id - 被操作角色的唯一 ID
   */
  const handleHide = (id: string) => {
    setCharacters(prev => prev.map(c => c.id === id ? { ...c, isHidden: true } : c));
  };

  /**
   * 处理角色的取消隐藏操作 (恢复显示)
   * @param id - 被操作角色的唯一 ID
   */
  const handleUnhide = (id: string) => {
    setCharacters(prev => prev.map(c => c.id === id ? { ...c, isHidden: false } : c));
  };

  /**
   * 处理角色列表的长按拖拽重排序
   * @param newOrder - 拖拽释放后产生的新的角色列表顺序 (仅包含未隐藏部分)
   * 重新排序后，需要将隐藏的角色合并回列表中，保证数据完整
   */
  const handleReorder = (newOrder: Character[]) => {
    const pinned = newOrder.filter(c => c.isPinned);
    const unpinned = newOrder.filter(c => !c.isPinned);
    const hidden = characters.filter(c => c.isHidden);
    setCharacters([...pinned, ...unpinned, ...hidden]);
  };

  /**
   * filteredVisibleChars: 经过筛选、过滤、排序后最终应该展示在主列表中的角色数组
   * 1. 过滤掉被隐藏的角色
   * 2. 将置顶角色放在最前面
   * 3. 根据搜索词对角色姓名、性格或隐藏性癖进行文本匹配过滤
   */
  const filteredVisibleChars = useMemo(() => {
    const visible = characters.filter(c => !c.isHidden);
    const pinnedChars = visible.filter(c => c.isPinned);
    const unpinnedChars = visible.filter(c => !c.isPinned);
    const sortedVisible = [...pinnedChars, ...unpinnedChars];
    
    if (!searchTerm) return sortedVisible;
    const lowerSearch = searchTerm.toLowerCase();
    return sortedVisible.filter(c => 
      c.name.toLowerCase().includes(lowerSearch) ||
      (c.nickname || '').toLowerCase().includes(lowerSearch) ||
      (c.personality || '').toLowerCase().includes(lowerSearch) ||
      (c.identity || '').toLowerCase().includes(lowerSearch) ||
      (c.privateProfile?.fetishTags || []).some(tag => tag.toLowerCase().includes(lowerSearch))
    );
  }, [characters, searchTerm]);

  const hiddenChars = characters.filter(c => c.isHidden);

  const filteredGroups = useMemo(() => {
    if (!searchTerm) return groups;
    const lowerSearch = searchTerm.toLowerCase();
    return groups.filter(group =>
      group.name.toLowerCase().includes(lowerSearch) ||
      group.summary.toLowerCase().includes(lowerSearch) ||
      group.memberNames.some(name => name.toLowerCase().includes(lowerSearch)),
    );
  }, [groups, searchTerm]);

  return (
    <FullScreenModal isOpen={true} className="z-20">
      <div className="px-4 pt-4 pb-3 sticky top-0 z-10 border-b border-border-default/30">
        <div className="flex items-center justify-between mb-4">
          <h1 className="text-xl font-bold text-text-primary flex items-center gap-2">
            <BookUser className="w-6 h-6 text-pink-400" />
            同学录
          </h1>
          <button onClick={onClose} className="p-2 glass rounded-full hover-fill transition-colors shadow-sm">
            <ChevronLeft className="w-5 h-5 text-text-primary" />
          </button>
        </div>

        <div className="grid grid-cols-2 gap-2 mb-3 p-1 rounded-2xl bg-surface border border-border-default">
          <button
            onClick={() => setTab('mates')}
            className={`py-2 rounded-xl text-sm font-bold transition-colors ${tab === 'mates' ? 'bg-surface-solid text-pink-500 shadow-sm' : 'text-text-secondary hover-fill'}`}
          >
            同学
          </button>
          <button
            onClick={() => setTab('groups')}
            className={`py-2 rounded-xl text-sm font-bold transition-colors ${tab === 'groups' ? 'bg-surface-solid text-pink-500 shadow-sm' : 'text-text-secondary hover-fill'}`}
          >
            群组
          </button>
        </div>
        
        <div className="relative">
          <Search className="w-4 h-4 text-text-secondary absolute left-3 top-1/2 -translate-y-1/2" />
          <input 
            type="text" 
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            placeholder={tab === 'groups' ? '搜索群名或成员...' : '搜索名字、性格或身份...'} 
            className="w-full glass border border-border-default rounded-2xl py-2 pl-9 pr-4 text-sm focus:outline-none focus:ring-2 focus:ring-pink-200 focus:border-pink-300 transition-all shadow-sm bg-white/40 placeholder:text-text-secondary"
          />
        </div>
      </div>

      <div 
        className="flex-1 min-h-0 overflow-y-auto overflow-x-hidden px-4 pt-3 pb-6 space-y-3 hide-scrollbar relative select-none cursor-grab active:cursor-grabbing touch-none"
        {...dragProps} ref={dragProps.ref}
      >
        {tab === 'mates' ? (
        <Reorder.Group axis="y" values={filteredVisibleChars} onReorder={handleReorder} className="space-y-3">
          {filteredVisibleChars.map((char) => (
            <LongPressReorderItem key={char.id} char={char} disabled={!!searchTerm}>
              <SwipeableItem 
                isPinned={!!char.isPinned} 
                onPin={() => handlePin(char.id, !!char.isPinned)} 
                onHide={() => handleHide(char.id)}
              >
                <Card
                  onClick={() => setActiveChat({ type: 'dm', target: getChatDisplayName(char), characterId: char.id })}
                  className="p-3 flex items-center gap-4 cursor-pointer hover-fill transition-colors relative"
                >
                  {char.isPinned && (
                    <div className="absolute top-2 left-2 z-10 text-pink-500 bg-white/80 rounded-full p-0.5 shadow-sm">
                      <Pin className="w-3 h-3" />
                    </div>
                  )}
                  <button
                    type="button"
                    onClick={event => {
                      event.stopPropagation();
                      onCharacterClick(char);
                    }}
                    className="shrink-0"
                  >
                    {char.avatar ? (
                      <img src={char.avatar} className="w-14 h-14 rounded-full object-cover border-2 border-border-default shadow-sm" alt={char.name}/>
                    ) : (
                      <div className="w-14 h-14 rounded-full bg-gradient-to-br from-pink-100 to-rose-100 flex items-center justify-center text-pink-500 font-bold text-lg border-2 border-border-default shadow-sm">
                        {char.name[0]}
                      </div>
                    )}
                  </button>
                  
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center justify-between mb-1">
                      <span className="font-bold text-text-primary text-base truncate">{char.name}</span>
                      <div className="flex items-center gap-1 soft-chip px-2 py-0.5 rounded-full shrink-0">
                        <Heart className="w-3 h-3 fill-current" />
                        <span className="text-xs font-bold">{char.affinity}</span>
                      </div>
                    </div>
                    {char.nickname && char.nickname !== char.name ? (
                      <div className="text-[11px] text-text-secondary truncate mb-0.5">{char.nickname}</div>
                    ) : null}
                    <div className="text-sm text-text-secondary line-clamp-1">
                      {getLatestPreview(getThreadMessages(threads, 'dm', getChatDisplayName(char), getCharacterChatAliases(char)))}
                    </div>
                  </div>
                </Card>
              </SwipeableItem>
            </LongPressReorderItem>
          ))}
        </Reorder.Group>
        ) : (
          <div className="space-y-3">
            {filteredGroups.map(group => (
              <Card
                key={group.id}
                onClick={() => setActiveChat({ type: 'group', target: group.name })}
                className="p-3 flex items-center gap-4 cursor-pointer hover-fill transition-colors"
              >
                <div className="w-14 h-14 rounded-full bg-sky-50 text-sky-500 flex items-center justify-center border-2 border-border-default shadow-sm shrink-0">
                  <Users className="w-6 h-6" />
                </div>
                <div className="flex-1 min-w-0">
                  <div className="flex items-center justify-between mb-1">
                    <span className="font-bold text-text-primary text-base truncate">{group.name}</span>
                    <span className="text-[10px] text-text-secondary shrink-0">{group.memberNames.length} 人</span>
                  </div>
                  <div className="text-sm text-text-secondary line-clamp-1">
                    {getLatestPreview(getThreadMessages(threads, 'group', group.name))}
                  </div>
                </div>
              </Card>
            ))}
            {filteredGroups.length === 0 && (
              <div className="text-center text-text-secondary text-sm mt-16 leading-relaxed">
                暂无群组。
                <br />
                AI 会把班级、宿舍、社团等群资料写入 MVU 后，这里才会出现。
              </div>
            )}
          </div>
        )}
      </div>

      <button 
        onClick={() => setShowHiddenModal(true)}
        className="absolute bottom-4 right-4 w-12 h-12 glass rounded-full flex items-center justify-center shadow-lg border border-border-default hover-fill transition-colors z-30 text-text-secondary"
      >
        <Trash2 className="w-5 h-5" />
      </button>

      {/* Hidden Characters Modal */}
      <BottomSheetModal 
        isOpen={showHiddenModal} 
        onClose={() => setShowHiddenModal(false)}
        className="h-[70%] p-5 bg-white/90 backdrop-blur-xl"
      >
        <div className="flex justify-between items-center mb-4 mt-2">
          <h2 className="text-lg font-bold text-text-primary">已隐藏的同学</h2>
        </div>
        <div 
          className="flex-1 overflow-y-auto overflow-x-hidden space-y-3 hide-scrollbar select-none cursor-grab active:cursor-grabbing touch-none"
          {...hiddenDragProps} ref={hiddenDragProps.ref}
        >
              {hiddenChars.map(char => (
                <SwipeableItem 
                  key={char.id}
                  isPinned={false} 
                  onPin={() => {}} 
                  onHide={() => handleUnhide(char.id)}
                  isUnhideMode={true}
                >
                  <Card className="p-3 flex items-center gap-4 bg-white/40">
                    {char.avatar ? (
                      <img src={char.avatar} className="w-12 h-12 rounded-full object-cover opacity-50 grayscale" alt={char.name}/>
                    ) : (
                      <div className="w-12 h-12 rounded-full bg-gray-200 flex items-center justify-center text-text-secondary font-bold opacity-50">
                        {char.name[0]}
                      </div>
                    )}
                    <div className="flex-1 text-text-secondary min-w-0">
                      <div className="font-bold truncate">{char.name}</div>
                      {char.identity && <div className="text-xs line-clamp-1 mt-0.5">{char.identity}</div>}
                    </div>
                  </Card>
                </SwipeableItem>
              ))}
              {hiddenChars.length === 0 && (
                <div className="text-center text-text-secondary text-sm mt-10">暂无隐藏的同学</div>
              )}
            </div>
      </BottomSheetModal>

      {activeChat && (
        <ChatScreen
          type={activeChat.type}
          targetName={activeChat.target}
          player={player}
          characters={characters}
          group={groups.find(item => item.name === activeChat.target)}
          messages={getThreadMessages(
            threads,
            activeChat.type,
            activeChat.target,
            activeChat.type === 'dm'
              ? getCharacterChatAliases(characters.find(item => item.id === activeChat.characterId))
              : [],
          )}
          nowTs={nowTs}
          onClose={() => setActiveChat(null)}
          onAvatarClick={onCharacterClick}
        />
      )}
    </FullScreenModal>
  );
}
