import { MvuTime } from '../hooks/useMvuData';
import { ChatMessageItem, ChatThread } from '../types';
import { extractBlocks, parseForumClock, readAssistantMessages } from './forumParser';

function normalizeChatType(value: string): 'dm' | 'group' {
  const text = String(value || '').trim();
  if (/群/.test(text) || text === 'group') return 'group';
  return 'dm';
}

function parseMessage(block: ReturnType<typeof extractBlocks>[number], fallbackId: string, messageId: number, now?: Partial<MvuTime> | null): ChatMessageItem | null {
  const content = (block.inner || '').replace(/<[^>]+>/g, '').trim() || String(block.attrs.内容 || '').trim();
  const senderName = block.attrs.发送者 || block.attrs.作者 || '匿名同学';
  if (!content) return null;
  return {
    id: block.attrs.id || fallbackId,
    senderName,
    content,
    timestamp: parseForumClock(block.attrs.时间 || '', messageId, now),
  };
}

function parseThread(block: ReturnType<typeof extractBlocks>[number], fallbackId: string, messageId: number, now?: Partial<MvuTime> | null): ChatThread | null {
  const type = normalizeChatType(block.attrs.类型);
  const target = String(block.attrs.对象 || block.attrs.群名 || '').trim();
  if (!target) return null;
  const messages = extractBlocks(block.inner, '消息')
    .map((item, index) => parseMessage(item, `${block.attrs.id || fallbackId}-m${index + 1}`, messageId, now))
    .filter((item): item is ChatMessageItem => Boolean(item));
  return {
    id: block.attrs.id || fallbackId,
    type,
    target,
    messages,
  };
}

export function parseChatThreadsFromText(text: string, messageId = 0, now?: Partial<MvuTime> | null): ChatThread[] {
  const containers = extractBlocks(text, '聊天');
  const sources = containers.length ? containers.map(block => block.inner) : [text];
  return sources.flatMap((source, blockIndex) =>
    extractBlocks(source, '会话').map((block, index) =>
      parseThread(block, `chat-${messageId}-${blockIndex + 1}-${index + 1}`, messageId, now),
    ),
  ).filter((item): item is ChatThread => Boolean(item));
}

function mergeMessages(current: ChatMessageItem[] = [], incoming: ChatMessageItem[] = []): ChatMessageItem[] {
  const map = new Map<string, ChatMessageItem>();
  [...current, ...incoming].forEach(message => {
    const prev = map.get(message.id);
    if (!prev) {
      map.set(message.id, message);
      return;
    }
    map.set(message.id, { ...prev, ...message, pending: false });
  });
  return [...map.values()].sort((a, b) => a.timestamp - b.timestamp);
}

export function mergeChatThreads(current: ChatThread[], incoming: ChatThread[]): ChatThread[] {
  const map = new Map<string, ChatThread>();
  const keyOf = (thread: ChatThread) => thread.id || `${thread.type}:${thread.target}`;
  [...current, ...incoming].forEach(thread => {
    const key = keyOf(thread);
    const prev = map.get(key);
    if (!prev) {
      map.set(key, thread);
      return;
    }
    map.set(key, {
      ...prev,
      ...thread,
      messages: mergeMessages(prev.messages, thread.messages),
    });
  });
  return [...map.values()];
}

export function loadChatThreadsFromChat(now?: Partial<MvuTime> | null): ChatThread[] {
  const threads = readAssistantMessages().flatMap(item => parseChatThreadsFromText(item.message, item.message_id, now));
  return mergeChatThreads([], threads);
}

export function getChatDisplayName(character: { name: string; nickname?: string }): string {
  return String(character.nickname || character.name || '').trim();
}

export function getCharacterChatAliases(character?: { name: string; nickname?: string } | null): string[] {
  if (!character) return [];
  return [character.name, character.nickname]
    .map(item => String(item || '').trim())
    .filter(Boolean);
}

export function characterMatchesChatName(character: { name: string; nickname?: string }, name: string): boolean {
  const target = String(name || '').trim();
  if (!target) return false;
  return [character.name, character.nickname].some(item => String(item || '').trim() === target);
}

export function getThreadMessages(threads: ChatThread[], type: 'dm' | 'group', target: string, aliases: string[] = []): ChatMessageItem[] {
  const names = new Set([target, ...aliases].map(item => String(item || '').trim()).filter(Boolean));
  const matched = threads.filter(thread => thread.type === type && names.has(thread.target));
  return mergeMessages([], matched.flatMap(thread => thread.messages));
}

export function getLatestPreview(messages: ChatMessageItem[]): string {
  const last = messages[messages.length - 1];
  return last ? `${last.senderName}：${last.content}` : '暂无聊天';
}
